  /* v89: RECONFERE A LICENÇA DE TEMPOS EM TEMPOS (a cada 10–15 min, tempo sorteado).
     Antes ela só era conferida quando a página carregava — quem nunca recarregava (ex.: 24/7)
     continuava usando depois de a licença vencer/ser bloqueada. Pra não derrubar ninguém por
     falha de internet, só age depois de DUAS conferências negativas seguidas (a 2ª, 2–3 min depois):
     aí avisa e recarrega a página, e o loader barra o painel. Não roda durante captcha. */
  (function reconferirLicenca() {
    if (typeof window.__ORK_REVALIDAR_LICENCA__ !== 'function') { return; }
    var negativas = 0;
    function entre(a, b) { return Math.floor(a + Math.random() * (b - a + 1)); }
    function agendar(ms) { setTimeout(conferir, ms); }
    function conferir() {
      if (window.__ORK_CAPTCHA_BLOQUEADO__) { agendar(entre(60000, 120000)); return; }
      var respondeu = false;
      var limite = setTimeout(function () { if (!respondeu) { respondeu = true; agendar(entre(600000, 900000)); } }, 30000); // sem resposta: não conta
      try {
        window.__ORK_REVALIDAR_LICENCA__(function (ok) {
          if (respondeu) { return; }
          respondeu = true; clearTimeout(limite);
          if (ok) { negativas = 0; agendar(entre(600000, 900000)); return; }
          negativas++;
          console.warn('[OROCHIKING] Licença: conferência negativa (' + negativas + '/2).');
          if (negativas < 2) { agendar(entre(120000, 180000)); return; }
          try {
            var av = document.createElement('div');
            av.style.cssText = 'position:fixed;top:14px;left:50%;transform:translateX(-50%);z-index:2147483647;background:linear-gradient(165deg,#1a1a1a,#050505);' +
              'border:1px solid #f0b90b;border-radius:12px;padding:12px 16px;color:#eee;font:13px "Segoe UI",Arial,sans-serif;box-shadow:0 12px 30px rgba(0,0,0,.7)';
            av.innerHTML = '<b style="color:#ffd84d">🔒 OROCHIKING</b><br>Sua licença não está mais ativa (vencida ou bloqueada). A página vai recarregar e o painel será desligado.';
            document.body.appendChild(av);
          } catch (e) {}
          setTimeout(function () { location.reload(); }, 8000);
        });
      } catch (e) { respondeu = true; clearTimeout(limite); agendar(entre(600000, 900000)); }
    }
    agendar(entre(600000, 900000));
  })();

  /* ============================================================
     MANTER A ABA ATIVA EM SEGUNDO PLANO

     O Chrome e outros navegadores, de propósito, "atrasam" o setTimeout/
     setInterval de uma aba em segundo plano (minimizada ou em outra aba
     do navegador) pra economizar bateria/CPU — depois de alguns minutos
     em segundo plano, o navegador pode deixar até 1 MINUTO entre uma
     chamada e outra, mesmo configurado pra rodar a cada poucos segundos.
     É exatamente por isso que a Cunhagem (e qualquer timer do painel)
     ficava atrasada só quando a aba não estava em foco.

     A técnica pra evitar isso é tocar um som praticamente inaudível sem
     parar: navegadores tratam abas "tocando algo" como abas ativas de
     verdade e NÃO aplicam esse limite, porque cortar o áudio no meio
     seria perceptível pro usuário. Isso vale pra TODOS os timers do
     painel (Farm Hard, loop do Ataque, Cunhar Moedas, Coletor Hard
     Farming, monitor de sessão, monitor de captcha) — não precisa
     mexer em cada um separadamente.
  ============================================================ */
  (function manterAbaAtivaEmSegundoPlano() {
    try {
      var AudioCtx = window.AudioContext || window.webkitAudioContext;
      if (!AudioCtx) { return; }
      var ctx = new AudioCtx();
      var osc = ctx.createOscillator();
      var gain = ctx.createGain();
      gain.gain.value = 0.00001; // praticamente inaudível
      osc.frequency.value = 20;  // abaixo do que o ouvido humano capta
      osc.type = 'sine';
      osc.connect(gain);
      gain.connect(ctx.destination);
      osc.start(0);

      // Navegadores exigem uma interação do usuário pra "destravar" áudio
      // (política de autoplay) — o AudioContext nasce suspenso até isso
      // acontecer. Qualquer clique/tecla no painel já serve pra destravar.
      function tentarRetomar() {
        if (ctx.state === 'suspended' && typeof ctx.resume === 'function') {
          ctx.resume().catch(function () {});
        }
      }
      tentarRetomar();
      ['click', 'keydown', 'touchstart'].forEach(function (evento) {
        document.addEventListener(evento, tentarRetomar, { passive: true });
      });
      // se o navegador suspender nele de novo com o tempo, insiste sozinho
      setInterval(tentarRetomar, 15000);

      window.__ORK_ABA_ATIVA__ = true;
      console.log('[OROCHIKING] Mantendo a aba ativa em segundo plano — timers não devem mais atrasar quando minimizada.');
    } catch (e) {
      console.warn('[OROCHIKING] não consegui ativar o "manter aba ativa":', e);
    }
  })();

