    try { var okTs = +sessionStorage.getItem('ork_captcha_ok') || 0; if (okTs && Date.now() - okTs < 40000 && !captchaNaTela()) { return; } } catch (e) {}
    if (captchaNaTela()) { ativarModoCaptcha(); return; }
