    // que recarrega pra o desafio aparecer na tela (com alarme) — senão ninguém via o captcha
    try { if (window.top !== window.self) { localStorage.setItem('ork_captcha_iframe', String(Date.now())); } } catch (e) {}
    if (alarmeAtivo) return;
    alarmeAtivo = true;
    pararFarmHard();
    var telaOn = orkCaptchaTelaLigado();
    mostrarOverlay(); // já se auto-gateia pelo toggle
    pararSomAtual = tocarAlarme(); // já se auto-gateia pelo toggle do som
