    try { sessionStorage.setItem('ork_captcha_ok', String(Date.now())); } catch (e) {}
    try { localStorage.removeItem('ork_captcha_iframe'); } catch (e) {}
    try { sessionStorage.removeItem(ORK_CAP_RELOAD); } catch (e) {} // v208: zera as recargas do modo discreto
    removerOverlay();
    if (pararSomAtual) { pararSomAtual(); pararSomAtual = null; }
    orkAvisosForaDaTela(false);
