                var sc = document.getElementById("syncChegada"); if (sc && !sc.checked) { sc.checked = true; $(sc).trigger("change"); }
                info.css("color", "#7ed17e").text("✔ Sincronizar chegada ligado pra " + z(d.getHours()) + ":" + z(d.getMinutes()) + ":" + z(d.getSeconds()) + ".");
