  function checaOcultar() {
    return document.URL.indexOf('screen=info_player') !== -1;
  }
  function rodarOcultar() {
    (function () {
      function ocultarComandos() {
        var seletores = [
          'table #villages_list tbody tr td span[class="icon command command-attack-ally"]',
          'table #villages_list tbody tr td span[class="icon command command-attack"]',
          'table #villages_list tbody tr td span[class="icon command command-support-ally"]',
          'table #villages_list tbody tr td span[class="icon command command-support"]'
        ];
        var total = 0;
        seletores.forEach(function (sel) {
          document.querySelectorAll(sel).forEach(function (span) {
            var linha = span.closest('tr');
            if (linha) { linha.remove(); total++; }
          });
        });
        return total;
      }
    
      var linkMostrarTodas = null;
      document.querySelectorAll('#villages_list a').forEach(function (a) {
        var t = (a.textContent || '').toLowerCase();
        if (t.indexOf('exibir') !== -1 && t.indexOf('aldeia') !== -1) { linkMostrarTodas = a; }
      });

      // Depois de ocultar, já oferece o Coletar Perfil NESTA página: coletar pelo painel
      // recarregava o perfil e as aldeias ocultadas voltavam.
      function terminar() {
        var ocultadas = ocultarComandos();
        orkOferecerColetaPerfil(ocultadas);
      }

      if (linkMostrarTodas) {
        linkMostrarTodas.click();
        // espera a lista completa terminar de carregar (a quantidade de linhas parar de mudar)
        var ultimo = -1, iguais = 0, voltas = 0;
        (function esperarLista() {
          voltas++;
          var n = document.querySelectorAll('#villages_list tr').length;
          iguais = (n === ultimo) ? iguais + 1 : 0;
          ultimo = n;
          if ((iguais >= 3 && voltas >= 4) || voltas >= 25) { terminar(); return; }
          setTimeout(esperarLista, 400);
        })();
      } else {
        terminar();
      }
    })();

  }

  // Popup "Coletar as aldeias restantes" logo depois do Ocultar Perfil (mesma página, sem recarregar)
  function orkOferecerColetaPerfil(ocultadas) {
    var velho = document.getElementById('ork-coleta-apos-ocultar');
    if (velho) { velho.remove(); }
    var restantes = 0;
    document.querySelectorAll('#villages_list td').forEach(function (td) {
      if (/^\s*\d+\|\d+\s*$/.test(td.textContent || '')) { restantes++; }
    });
    var caixa = document.createElement('div');
    caixa.id = 'ork-coleta-apos-ocultar';
    caixa.style.cssText = 'position:fixed;top:14px;left:50%;transform:translateX(-50%);background:linear-gradient(165deg,rgba(26,26,26,.98),rgba(8,8,8,.99));' +
      'border:1px solid #8a6d00;border-radius:12px;padding:12px 14px;z-index:2147483600;width:280px;' +
      'font-family:"Segoe UI",Arial,sans-serif;color:#eee;box-shadow:0 14px 34px rgba(0,0,0,.75),0 0 0 3px rgba(232,172,10,.18)';
    caixa.innerHTML =
      '<div style="display:flex;align-items:center;gap:6px;margin-bottom:6px">' +
        '<span style="flex:1;font-weight:800;color:#ffd84d;font-size:12.5px">🙈 Atacadas ocultadas</span>' +
        '<span id="ork-coleta-apos-x" title="Fechar" style="cursor:pointer;color:#888;font-weight:800;font-size:15px">&times;</span></div>' +
      '<div style="font-size:11.5px;color:#bbb;line-height:1.45;margin-bottom:9px">' +
        '<b style="color:#fff">' + ocultadas + '</b> aldeia(s) com comando a caminho ficaram de fora. ' +
        'Restam <b style="color:#fff">' + restantes + '</b> aldeia(s) livres na tela.</div>' +
      '<button id="ork-coleta-apos-btn" style="width:100%;background:linear-gradient(100deg,#e8ac0a,#ffdc63);' +
        'color:#141200;border:none;border-radius:7px;padding:8px 10px;cursor:pointer;font-weight:800;font-size:12px">👤 Coletar as aldeias restantes</button>' +
      '<div style="font-size:9.5px;color:#777;margin-top:6px">Coleta desta mesma página — não recarregue antes de clicar, senão as ocultadas voltam.</div>';
    document.body.appendChild(caixa);
    document.getElementById('ork-coleta-apos-x').addEventListener('click', function () { caixa.remove(); });
    document.getElementById('ork-coleta-apos-btn').addEventListener('click', function () {
      caixa.remove();
      try { limparPendente(); } catch (e) {}
      try { rodarPerfil(); } catch (e) {
        console.error('[OROCHIKING] Coletar Perfil', e);
        alert('OROCHIKING: erro ao coletar: ' + (e && e.message ? e.message : e));
      }
    });
  }

