  function nobAgendar() {
    var c = nobLer();
    if (!c.ativo) { return; }
    if (nobTimer) { clearTimeout(nobTimer); }
    nobTimer = setTimeout(function () {
      var n = nobLer();
      if (!n.ativo) { return; }
      if (n.proximoEm > Date.now() + 1000) { nobAgendar(); return; }
      nobRodarCiclo();
    }, Math.max(0, (c.proximoEm || 0) - Date.now()));
  }
  function nobRetomar() {
    var c = nobLer();
    if (!c.ativo) { return; }
    nobMostrarBolinha();
    if (c.proximoEm && c.proximoEm > Date.now()) { nobAgendar(); return; }
    nobRodarCiclo();
  }
  // Parar vale pra TUDO que estiver rodando o Nobre: esta aba, outras abas do mesmo mundo e o 24/7 (tira o Noblar da sequência)
  function nobParar(motivo, soEstaAba) {
    nobGeracao++;
    if (!soEstaAba) {
      try { localStorage.setItem('ork_nobre_parar_' + ((window.game_data && game_data.world) || ''), String(Date.now())); } catch (e) {}
      try {
        var a = autoLer();
        if (a.ativo && autoSeqAtiva(a).indexOf('nobre') !== -1) {
          a.seq = autoSeqCompleta(a).map(function (x) { return { id: x.id, on: x.id === 'nobre' ? false : x.on }; });
          autoGravar(a);
          nobLog('Noblar tirado da sequência do 24/7 (o resto do 24/7 continua).');
        }
      } catch (e) {}
    }
    // parou = começa do zero na próxima vez (as configurações escolhidas ficam; o histórico de alvos/explorações é apagado)
    var c = nobLer(); c.ativo = false; c.proximoEm = 0; c.alvos = []; c.explorados = []; c.ultimo = null; nobGravar(c);
    if (nobTimer) { clearTimeout(nobTimer); nobTimer = null; }
    if (nobRelogio) { clearInterval(nobRelogio); nobRelogio = null; }
    nobSoltarTrava();
    var b = document.getElementById('ork-nob-bolinha'); if (b) { b.remove(); }
    if (motivo) { nobLog('parado (' + motivo + ').'); }
  }


  // Parar apertado em OUTRA aba: para aqui também
  window.addEventListener('storage', function (ev) {
    try {
      if (ev.key !== 'ork_nobre_parar_' + ((window.game_data && game_data.world) || '')) { return; }
      var c = nobLer();
      if (c.ativo || nobRodando) { nobParar('parado em outra aba', true); }
    } catch (e) {}
  });
  // alguém rodando o Nobre em outra aba? (a trava é renovada a cada 5s por quem está rodando)
  function nobRodandoEmOutraAba() {
    try { var t = JSON.parse(localStorage.getItem(NOB_TRAVA) || 'null'); return !!(t && t.aba !== NOB_ABA && Date.now() - (t.ts || 0) < 20000); } catch (e) { return false; }
  }

  function nobMostrarBolinha() {
    if (document.getElementById('ork-nob-bolinha')) { return; }
    var b = document.createElement('div');
    b.id = 'ork-nob-bolinha';
    b.style.cssText = 'position:fixed;left:10px;bottom:20px;width:54px;height:54px;border-radius:50%;' +
      'background:linear-gradient(100deg,#e8ac0a,#ffdc63 50%,#e8ac0a);color:#1a1400;border:1px solid rgba(255,196,0,.35);' +
      'cursor:pointer;display:flex;align-items:center;justify-content:center;flex-direction:column;' +
      'box-shadow:0 10px 26px rgba(0,0,0,.5);font-family:"Segoe UI",Arial,sans-serif;z-index:9999996;line-height:1';
    b.innerHTML = '<span style="font-size:18px">👑</span><span id="ork-nob-tempo" style="font-size:8.5px;font-weight:800;margin-top:2px">NOB</span>';
    b.addEventListener('click', function () { if (confirm('Parar o Noblar Automático?\n\nO histórico de alvos e explorações é zerado — na próxima vez começa do zero (suas configurações ficam salvas). Nobres que já saíram continuam indo.')) { nobParar('parado pelo usuário'); } });
    document.body.appendChild(b);
    if (nobRelogio) { clearInterval(nobRelogio); }
    nobRelogio = setInterval(function () {
      var c = nobLer(), el = document.getElementById('ork-nob-tempo');
      if (!c.ativo || !el) { return; }
      if (window.__ORK_CAPTCHA_BLOQUEADO__) { el.textContent = window.orkTxtPausa('CAPTCHA'); return; }
      if (nobRodando || !c.proximoEm) { el.textContent = 'ENV'; return; }
      var s = Math.max(0, Math.round((c.proximoEm - Date.now()) / 1000));
      el.textContent = Math.floor(s / 60) + ':' + ('0' + (s % 60)).slice(-2);
      var cam = c.alvos.filter(function (a) { return a.status === 'caminho'; }).length;
      nobStatus('próximo ciclo em ' + el.textContent + ' • ' + cam + ' alvo(s) com nobre a caminho');
    }, 1000);
  }

  /* ---------- modal ---------- */
  /* v170: PRESETS (modelos salvos) do Noblar Automático e do Noblador de Player.
     A configuração normal continua POR ABA (fechou a aba, volta pro padrão). Preset salvo fica no navegador
     (localStorage) até você apagar ou limpar os dados do navegador. Guarda só AJUSTES — nunca o histórico/alvos. */
  var ORK_PRESET_FORA = ['ativo', 'alvos', 'explorados', 'proximoEm', 'ultimo', '_bloq', '_g', 'via247', 'ultimoMotivo'];
  function orkPresetsLer(chave) { try { var l = JSON.parse(localStorage.getItem(chave) || '[]'); return Array.isArray(l) ? l.filter(function (p) { return p && p.nome && p.cfg; }) : []; } catch (e) { return []; } }
  function orkPresetsGravar(chave, l) { try { localStorage.setItem(chave, JSON.stringify(l)); return true; } catch (e) { return false; } }
  function orkPresetLimpo(cfg) { var o = {}; Object.keys(cfg || {}).forEach(function (k) { if (ORK_PRESET_FORA.indexOf(k) === -1) { o[k] = cfg[k]; } }); return JSON.parse(JSON.stringify(o)); }
  // monta a barra de presets dentro de "box" e liga os botões
  function orkPresetsBarra(box, op) {
    if (!box) { return; }
    var inp = 'background:#111;border:1px solid rgba(255,255,255,.12);color:#ececec;padding:4px 6px;border-radius:6px;font-size:11px;box-sizing:border-box;font-family:inherit';
    var bt = 'background:#232323;color:#FFC400;border:1px solid #3a3a3a;border-radius:6px;padding:3px 9px;cursor:pointer;font-weight:700;font-size:10.5px;font-family:inherit;white-space:nowrap';
    function desenhar(sel) {
      var l = orkPresetsLer(op.chave);
      box.innerHTML = '<div style="display:flex;align-items:center;gap:5px;background:#141414;border:1px solid #262626;border-radius:8px;padding:5px 7px;margin-top:6px">' +
        '<span style="font-size:10.5px;color:#d9ab2e;font-weight:800;white-space:nowrap;cursor:help" data-dica="Salve a configuração do jeito que está (alvos, escolta, nobres, depois da conquista...) com um nome. Ela fica guardada no navegador até você apagar (ou limpar os dados do navegador) — mesmo fechando a aba. Pra usar: escolha o preset e clique em Carregar. O histórico de alvos nunca entra no preset.">📁 Presets</span>' +
        '<select class="ork-pr-sel" style="flex:1;min-width:0;' + inp + '">' + (l.length ? l.map(function (p, i) { return '<option value="' + i + '"' + (sel === p.nome ? ' selected' : '') + '>' + gerHtml(p.nome) + '</option>'; }).join('') : '<option value="">nenhum salvo ainda</option>') + '</select>' +
        '<button type="button" class="ork-pr-load" style="' + bt + '"' + (l.length ? '' : ' disabled') + ' data-dica="Carrega o preset escolhido nos campos (não liga nada — confira e clique em Ativar).">Carregar</button>' +
        '<button type="button" class="ork-pr-save" style="' + bt + '" data-dica="Salva os campos de agora como um preset (pede um nome; mesmo nome = substitui).">💾 Salvar</button>' +
        '<button type="button" class="ork-pr-del" style="' + bt + ';color:#ff7b7b"' + (l.length ? '' : ' disabled') + ' data-dica="Apaga o preset escolhido.">🗑</button></div>';
      var s = box.querySelector('.ork-pr-sel');
      box.querySelector('.ork-pr-save').addEventListener('click', function () {
        var atual = l[+s.value]; var nome = prompt('Nome do preset:', atual ? atual.nome : 'Meu preset'); if (!nome) { return; }
        nome = String(nome).trim().slice(0, 40); if (!nome) { return; }
        var cfg = orkPresetLimpo(op.lerCampos()), l2 = orkPresetsLer(op.chave).filter(function (p) { return p.nome !== nome; });
        l2.push({ nome: nome, cfg: cfg, em: Date.now() }); l2.sort(function (a, b) { return a.nome.localeCompare(b.nome); });
        if (orkPresetsGravar(op.chave, l2)) { try { UI.SuccessMessage('📁 Preset "' + nome + '" salvo.', 2500); } catch (e) {} } else { alert('Não consegui salvar (armazenamento do navegador cheio?).'); }
        desenhar(nome);
      });
      box.querySelector('.ork-pr-load').addEventListener('click', function () {
        var p = l[+s.value]; if (!p) { return; }
        var c = op.ler(); Object.keys(p.cfg).forEach(function (k) { c[k] = p.cfg[k]; }); op.gravar(c);
        try { UI.SuccessMessage('📁 Preset "' + p.nome + '" carregado.', 2500); } catch (e) {}
        op.reabrir();
      });
      box.querySelector('.ork-pr-del').addEventListener('click', function () {
        var p = l[+s.value]; if (!p || !confirm('Apagar o preset "' + p.nome + '"?')) { return; }
        orkPresetsGravar(op.chave, orkPresetsLer(op.chave).filter(function (x) { return x.nome !== p.nome; })); desenhar();
      });
    }
    desenhar();
  }
