            (rodandoAlgo ? '<button id="ork-nob-parar" style="flex:1;background:#2a1010;color:#ff6b6b;border:1px solid #4a1c1c;border-radius:8px;padding:7px 0;cursor:pointer;font-weight:700;font-size:11px;font-family:inherit">Parar</button>' : '') +
            '<button id="ork-nob-ok" style="flex:1.3;background:linear-gradient(100deg,#FFB800,#FFDD55);color:#141200;border:none;border-radius:8px;padding:7px 0;cursor:pointer;font-weight:800;font-size:11px;font-family:inherit">' + (c.ativo ? 'Salvar e rodar agora' : 'Ativar') + '</button>' +
          '</div>' +
        '</div>' +
      '</div>';
    document.body.appendChild(ov);
    var balao = autoLigarDicas(ov);
    function grupos() {
      var s = document.getElementById('ork-nob-grupo');
      var ops = [['0', 'Todas as aldeias']].concat((cat.grupos || []).map(function (g) { return [g.id, g.nome]; }));
      if (!ops.some(function (o) { return String(o[0]) === String(c.grupo); })) { ops.push([c.grupo, (c.grupoNome || c.grupo) + ' (salvo)']); }
      s.innerHTML = ops.map(function (o) { return '<option value="' + gerHtml(o[0]) + '"' + (String(o[0]) === String(c.grupo) ? ' selected' : '') + '>' + gerHtml(o[1]) + '</option>'; }).join('');
    }
    grupos();
    var escoltas = JSON.parse(JSON.stringify(c.escoltas || []));
    function desenharEscolta() {
      var box = document.getElementById('ork-nob-esc'), uns = nobUnidadesEscolta();
      box.innerHTML = escoltas.map(function (e, i) {
        return '<div style="display:flex;gap:4px;margin-top:3px">' +
          '<select class="ork-nob-eu" data-i="' + i + '" style="flex:1;' + inp + ';padding:3px 5px">' + uns.map(function (u) {
            return '<option value="' + u + '"' + (u === e.u ? ' selected' : '') + '>' + (NOB_NOME_UN[u] || u) + '</option>'; }).join('') + '</select>' +
          '<input class="ork-nob-en" data-i="' + i + '" type="number" min="0" placeholder="qtd" value="' + (e.n || '') + '" style="width:62px;' + inp + ';padding:3px 4px;text-align:center">' +
          '<button type="button" class="ork-nob-ex" data-i="' + i + '" style="width:24px;background:#2a1010;color:#ff6b6b;border:1px solid #4a1c1c;border-radius:5px;cursor:pointer;font-weight:800;padding:0">×</button></div>';
      }).join('') || '<div style="font-size:10px;color:#777">Sem escolta — o nobre vai sozinho.</div>';
      box.querySelectorAll('.ork-nob-eu').forEach(function (s) { s.addEventListener('change', function () { escoltas[+s.getAttribute('data-i')].u = s.value; }); });
      box.querySelectorAll('.ork-nob-en').forEach(function (s) { s.addEventListener('input', function () { escoltas[+s.getAttribute('data-i')].n = parseInt(s.value, 10) || 0; }); });
      box.querySelectorAll('.ork-nob-ex').forEach(function (b) { b.addEventListener('click', function () { escoltas.splice(+b.getAttribute('data-i'), 1); desenharEscolta(); }); });
    }
    desenharEscolta();
    document.getElementById('ork-nob-escadd').addEventListener('click', function () { escoltas.push({ u: 'light', n: 0 }); desenharEscolta(); });
    var refsTxt = (c.refs || []).map(function (r) { return r.x + '|' + r.y; });
    function desenharRefs() {
      var box = document.getElementById('ork-nob-refs');
      box.innerHTML = refsTxt.map(function (t, i) {
        return '<div style="display:flex;gap:4px;margin-top:3px">' +
          '<input class="ork-nob-rf" data-i="' + i + '" type="text" placeholder="500|500" value="' + gerHtml(t) + '" style="flex:1;' + inp + ';padding:3px 6px">' +
          '<button type="button" class="ork-nob-rx" data-i="' + i + '" style="width:24px;background:#2a1010;color:#ff6b6b;border:1px solid #4a1c1c;border-radius:5px;cursor:pointer;font-weight:800;padding:0">×</button></div>';
      }).join('') || '<div style="font-size:10px;color:#777">Nenhuma — pega as bárbaras mais perto das suas aldeias com nobre.</div>';
      box.querySelectorAll('.ork-nob-rf').forEach(function (s) { s.addEventListener('input', function () { refsTxt[+s.getAttribute('data-i')] = s.value; }); });
      box.querySelectorAll('.ork-nob-rx').forEach(function (b) { b.addEventListener('click', function () { refsTxt.splice(+b.getAttribute('data-i'), 1); desenharRefs(); }); });
    }
    desenharRefs();
    document.getElementById('ork-nob-refadd').addEventListener('click', function () {
      refsTxt.push(''); desenharRefs();
      var ins = document.querySelectorAll('#ork-nob-refs .ork-nob-rf'); if (ins.length) { ins[ins.length - 1].focus(); }
    });
    document.getElementById('ork-nob-lergr').addEventListener('click', async function () {
      var b = this; b.disabled = true; b.textContent = '...';
      try { var g = await gerLerGrupos(); cat = gerLerCatalogo() || {}; cat.grupos = g; gerGravarCatalogo(cat); } catch (e) {}
      b.disabled = false; b.textContent = '🔄'; grupos();
    });
    function fechar() { try { balao.remove(); } catch (e) {} ov.remove(); }
    function v(id) { return document.getElementById(id); }
    function lerCampos() {
      var n = nobLer(), s = v('ork-nob-grupo');
      n.grupo = s.value || '0'; n.grupoNome = s.options[s.selectedIndex] ? s.options[s.selectedIndex].textContent.replace(/ \(salvo\)$/, '') : '';
      n.espacamento = Math.max(1, parseInt(v('ork-nob-esp').value, 10) || 1);
      n.raio = Math.max(1, parseFloat(v('ork-nob-raio').value) || 40);
      n.pontosMin = Math.max(0, parseInt(v('ork-nob-pmin').value, 10) || 0);
      n.pontosMax = Math.max(n.pontosMin, parseInt(v('ork-nob-pmax').value, 10) || 13000);
      var tp = v('ork-nob-tipo').value; n.priorizarBonus = (tp === 'bonus'); n.soBonus = (tp === 'so'); n.espacoMinhas = v('ork-nob-espmin').checked;
      n.bonusTipos = [].slice.call(ov.querySelectorAll('#ork-nob-tipos input:checked')).map(function (i) { return i.getAttribute('data-t'); });
      n.nobres = Math.max(1, parseInt(v('ork-nob-qtd').value, 10) || 1);
      var rf = parseInt(v('ork-nob-ref').value, 10); n.reforco = Math.max(0, Math.min(5, isNaN(rf) ? 0 : rf));
      n.escoltas = escoltas.filter(function (e) { return e.u && (+e.n || 0) > 0; }).map(function (e) { return { u: e.u, n: Math.floor(+e.n) }; });
      n.full = v('ork-nob-full').checked; n.predio = v('ork-nob-predio').value || ''; nobFull = n.full; nobPredio = n.predio;
      n.maxSimult = Math.max(0, parseInt(v('ork-nob-max').value, 10) || 0);
      n.produzir = v('ork-nob-prod').checked;
      n.produzirMax = Math.max(1, parseInt(v('ork-nob-pmaxal').value, 10) || 1);
      n.produzirRaio = Math.max(1, parseInt(v('ork-nob-praio').value, 10) || 10);
      n.produzirAldeias = Math.max(0, parseInt(v('ork-nob-palds').value, 10) || 0);
      n.juntarNobres = !!v('ork-nob-juntar').checked;
      n.combinar = !!v('ork-nob-somar').checked;
      n.envioMin = Math.max(0.5, parseFloat(v('ork-nob-emin').value) || 2);
      n.envioMax = Math.max(n.envioMin, parseFloat(v('ork-nob-emax').value) || 4);
      n.intervaloUni = v('ork-nob-uni').value === 'seg' ? 'seg' : 'min';
      n.intervaloMin = Math.max(n.intervaloUni === 'seg' ? 10 : 1, parseFloat(v('ork-nob-int').value) || 30);
      n.pesquisar = v('ork-nob-pesq').checked;
      n.retirarApoio = v('ork-nob-retap').checked;
      n.recrutarEsp = Math.max(0, parseInt(v('ork-nob-rec').value, 10) || 0);
      n.explorarQtd = Math.max(0, Math.min(30, parseInt(v('ork-nob-exp').value, 10) || 0));
      n.vizinhasMin = Math.max(0, parseFloat(v('ork-nob-viz').value) || 0);
      n.refs = nobLerCoords(refsTxt.join(' '));
      n.reduzirAuto = v('ork-nob-reduz').checked;
      n.vizMin = Math.max(0, Math.min(8, parseInt(v('ork-nob-viz8').value, 10) || 0));
      n.continentes = nobLerConts(v('ork-nob-cont').value).map(function (k) { return k.nome; }).join(', ');
      n.prodMin = Math.max(0.3, parseFloat(v('ork-nob-prmin').value) || 0.7);
      n.prodMax = Math.max(n.prodMin, parseFloat(v('ork-nob-prmax').value) || 1.5);
      return n;
    }
    v('ork-nob-x').addEventListener('click', fechar);
