      var bt = bts.filter(function (b) { return /volta|devolv|retir|back|withdraw|zur[uü]ck|regres|terug|indietro/i.test((b.value || '') + ' ' + (b.textContent || '') + ' ' + b.name); })[0] || bts[0];
