      n.cTaxa = {}; ov.querySelectorAll('.mpp-ctx').forEach(function (e) { n.cTaxa[e.getAttribute('data-r')] = mppNum(e.value); });
      n.vGuardar = mppNum(q('#mpp-vguard').value); n.vPorVez = mppNum(q('#mpp-vvez').value);
