  function checaMercadoPP() { return !!(window.game_data && game_data.village && game_data.village.id); }
  function rodarMercadoPP() { mppAbrirModal(); }

  function checaGerente() { return !!(window.game_data && game_data.village && game_data.village.id); }
  function rodarGerente() { gerAbrirModal(); }

  /* ============================================================
     PESQUISAR EM MASSA (v96)
     Lê a tela Visualização → Pesquisa (overview_villages&mode=tech), página por página
     (1.000 aldeias cada), e manda pesquisar onde a bolinha está MARROM (pode pesquisar agora).
     Ferreiro simples: 1 passada. Ferreiro de níveis: repete passadas até o nível escolhido.
     Mesmo pedido do script clássico (TechOverview ajax_research_link + tech_id).
  ============================================================ */
  /* v98: a tela Edifícios/Pesquisa não se redesenha sozinha quando a ordem vai por trás.
     Enquanto você está nela, relê a página (1 pedido) e atualiza só a coluna da fila e as bolinhas. */
  async function orkRefrescarTela(tipo) {
    try {
      var r = await fetch(location.href, { credentials: 'include' });
      var doc = new DOMParser().parseFromString(await r.text(), 'text/html');
      if (tipo === 'cr') {
        doc.querySelectorAll('.row_a, .row_b').forEach(function (tr) {
          var vn = tr.querySelector('.quickedit-vn'); if (!vn) { return; }
          var meu = document.querySelector('.quickedit-vn[data-id="' + vn.getAttribute('data-id') + '"]'); if (!meu) { return; }
          var trMeu = meu.closest('tr'); if (!trMeu) { return; }
          var a = tr.children, b = trMeu.children; if (!a.length || a.length !== b.length) { return; }
          var ult = a.length - 1; // coluna "Construção" (fila)
          if (b[ult].innerHTML !== a[ult].innerHTML) { b[ult].innerHTML = a[ult].innerHTML; }
          for (var i = 0; i < ult; i++) { if (a[i].classList && a[i].classList.contains('upgrade_building') && b[i].textContent !== a[i].textContent) { b[i].textContent = a[i].textContent; } }
        });
      } else {
        doc.querySelectorAll('[id^="village_tech_order_"]').forEach(function (el) { var m = document.getElementById(el.id); if (m && m.innerHTML !== el.innerHTML) { m.innerHTML = el.innerHTML; } });
        doc.querySelectorAll('.rtt[id]').forEach(function (el) { var m = document.getElementById(el.id); if (m && m.className !== el.className) { m.className = el.className; } });
      }
    } catch (e) {}
  }
  // v99: mostra na hora (1 a 1) o que entrou na fila — sem pedido a mais
  function orkFilaPesquisaNaTela(vid, u, j) {
    try {
      var cel = document.getElementById('village_tech_order_' + vid); if (!cel) { return; }
      var html = j && (j.tech_order || (j.response && j.response.tech_order));
      if (html) { cel.innerHTML = html; return; }
      cel.insertAdjacentHTML('beforeend', '<img src="' + (window.image_base || '/graphic/') + 'unit/unit_' + u + '.png" title="' + u + '" style="width:16px;height:16px;vertical-align:middle">');
    } catch (e) {}
  }
  function orkFilaConstrucaoNaTela(vid, b) {
    try {
      var vn = document.querySelector('.quickedit-vn[data-id="' + vid + '"]'); if (!vn) { return; }
      var tr = vn.closest('tr'); if (!tr || !tr.lastElementChild) { return; }
      tr.lastElementChild.insertAdjacentHTML('beforeend', '<span class="queue_icon ork-fila-nova"><img src="' + (window.image_base || '/graphic/') + 'buildings/' + b + '.png" title="' + b + '" style="width:16px;height:16px;vertical-align:middle"></span>');
    } catch (e) {}
  }
  var pmRodando = false, pmParar = false;
  function pmLerCfg() {
    var p = { ativo: false, grupo: '0', unidades: null, nivel: 0, eMin: 0.5, eMax: 1.2 };
    try { var c = JSON.parse(localStorage.getItem('ork_pesqmassa_' + game_data.world) || 'null'); if (c) { for (var k in c) { p[k] = c[k]; } } } catch (e) {}
    return p;
  }
  function pmGravarCfg(c) { try { localStorage.setItem('ork_pesqmassa_' + game_data.world, JSON.stringify(c)); } catch (e) {} }
  // lê uma página da visualização de pesquisa: bolinhas por aldeia/unidade + o link de pesquisa do jogo
  async function pmLerPagina(grupo, pagina) {
    var r = await fetch(game_data.link_base_pure + 'overview_villages&mode=tech&group=' + encodeURIComponent(grupo) + '&page=' + pagina, { credentials: 'include' });
    var html = await r.text();
    var doc = new DOMParser().parseFromString(html, 'text/html');
    var m = html.match(/ajax_research_link["']?\s*:\s*["']([^"']+)["']/);
    var link = m ? m[1].replace(/\\\//g, '/').replace(/\\u0026/g, '&').replace(/&amp;/g, '&') : '';
    var bolas = [];
    doc.querySelectorAll('.rtt[id]').forEach(function (el) {
      var mm = (el.id || '').match(/^(\d+)_([a-z]+)$/); if (!mm) { return; }
      var cl = ' ' + (el.className || '') + ' ';
      var est = /\sbrown\s/.test(cl) ? 'pode' : /\syellow\s/.test(cl) ? 'fila' : /\sgreen\s/.test(cl) ? 'pronta' : /\sgrey\s|\sgray\s/.test(cl) ? 'nao' : 'outro';
      var cel = el.closest('td') || el, nv = (cel.textContent || '').replace(/[^0-9]/g, '');
      bolas.push({ vid: mm[1], u: mm[2], est: est, nivel: nv === '' ? null : +nv });
    });
    return { bolas: bolas, link: link };
  }
  async function pmLerTudo(grupo, progresso) {
    var todas = [], vistos = {}, link = '';
    for (var p = 0; p < 30 && !pmParar; p++) {
      var pg = await pmLerPagina(grupo, p);
      if (pg.link) { link = pg.link; }
      var novas = pg.bolas.filter(function (b) { return !vistos[b.vid + '_' + b.u]; });
      if (!novas.length) { break; } // passou da última página (o jogo repete a primeira)
      novas.forEach(function (b) { vistos[b.vid + '_' + b.u] = 1; todas.push(b); });
      if (progresso) { progresso('lendo página ' + (p + 1) + ' — ' + Object.keys(todas.reduce(function (a, b) { a[b.vid] = 1; return a; }, {})).length + ' aldeia(s)'); }
      await gerEsperar(gerEntre(300, 700));
    }
    return { bolas: todas, link: link };
  }
  function pmUrl(link, vid) {
    var csrf = window.csrf_token || (window.game_data && game_data.csrf) || '';
    var url = link ? link.replace(/village=\d+/, 'village=' + vid) : ('/game.php?village=' + vid + '&screen=smith&ajaxaction=research');
    if (!/[?&]h=/.test(url)) { url += (url.indexOf('?') === -1 ? '?' : '&') + 'h=' + encodeURIComponent(csrf); }
    return url;
  }
  async function pmExecutar(cfg, simular, mostrar) { var _rpv = await orkFilaEntrar('Pesquisa', simular); try { return await pmExecutarInterno(cfg, simular, mostrar); } finally { _rpv(); } }
  async function pmExecutarInterno(cfg, simular, mostrar) {
    pmRodando = true; pmParar = false;
    var res = { pesquisou: 0, recusou: 0, passadas: 0, porUn: {}, erro: '' };
    try {
      var nivelAlvo = Math.max(1, cfg.nivel || 1);
      var sel = {}; (cfg.unidades || []).forEach(function (u) { sel[u] = 1; });
      for (var passada = 1; passada <= nivelAlvo && !pmParar; passada++) {
        res.passadas = passada;
        var lido = await pmLerTudo(cfg.grupo || '0', function (t) { mostrar('Passada ' + passada + '/' + nivelAlvo + ': ' + t); });
        var cont = { pode: 0, fila: 0, pronta: 0, nao: 0, outro: 0 };
        var alvo = lido.bolas.filter(function (b) {
          if (!sel[b.u]) { return false; }
          cont[b.est]++;
          return b.est === 'pode' && (b.nivel === null || b.nivel < nivelAlvo);
        });
        res.aldeias = Object.keys(lido.bolas.reduce(function (a, b) { a[b.vid] = 1; return a; }, {})).length;
        res.cont = cont;
        if (simular) { res.aPesquisar = alvo.length; alvo.forEach(function (b) { res.porUn[b.u] = (res.porUn[b.u] || 0) + 1; }); break; }
        if (!alvo.length) { break; }
        var okPassada = 0;
        for (var i = 0; i < alvo.length && !pmParar; i++) {
          while (window.__ORK_CAPTCHA_BLOQUEADO__ && !pmParar) { mostrar(window.orkTxtPausa('Captcha — esperando você resolver...')); await gerEsperar(gerEntre(3000, 5000)); }
          if (pmParar) { break; }
          var b = alvo[i];
          var r = await gerPost(pmUrl(lido.link, b.vid), 'tech_id=' + encodeURIComponent(b.u) + '&source=' + b.vid);
          if (r.ok) { okPassada++; res.pesquisou++; res.porUn[b.u] = (res.porUn[b.u] || 0) + 1; orkFilaPesquisaNaTela(b.vid, b.u, r.j); try { var bol = document.getElementById(b.vid + '_' + b.u); if (bol) { bol.classList.remove('brown'); bol.classList.add('yellow'); } } catch (e) {} } else { res.recusou++; res.ultimoErro = r.erro; }
          mostrar('Passada ' + passada + '/' + nivelAlvo + ': ' + (i + 1) + '/' + alvo.length + ' — ' + res.pesquisou + ' pesquisa(s) mandada(s)' + (res.recusou ? ', ' + res.recusou + ' recusada(s) (recurso/fila?)' : ''), (i + 1) / alvo.length);
          var a = Math.max(0.2, +cfg.eMin || 0.5), z = Math.max(a, +cfg.eMax || 1.2);
          await gerEsperar(gerEntre(Math.round(a * 1000), Math.round(z * 1000)));
        }
        if (!okPassada) { break; } // nada passou nessa passada: não adianta repetir agora
      }
    } catch (e) { res.erro = (e && e.message) || String(e); }
    pmRodando = false;
    if (!simular && res.pesquisou && pmNaTela()) { await orkRefrescarTela('pm'); }
    return res;
  }
