      ov.querySelectorAll('.ci-up').forEach(function (b) { b.addEventListener('click', function () { var i = +b.getAttribute('data-i'); var t = ps[i - 1]; ps[i - 1] = ps[i]; ps[i] = t; desenharModelos(); }); });
