      if (!ok.length) { info.innerHTML = '<span style="color:#ff8080">Não reconheci. Cole o código do modelo do GC ou uma lista (Nome do edifício + nível, um por linha).</span>'; return; }
      modelos[mAtual].passos = ok; desenharModelos(); desenharRegras(); q('#ci-colartxt').value = '';
