      n.reduzir = !!q('#ci-reduz').checked; n.finalizarGratis = !!q('#ci-fingratis').checked; n.desconto20 = !!q('#ci-desc').checked; n.descontoNivel = Math.max(1, num(q('#ci-descniv').value, 10)); n.reduzirMin = Math.max(0, num(q('#ci-reduzmin').value, 60)); n.reduzirMax = Math.max(0, Math.min(50, num(q('#ci-reduzmax').value, 3)));
