    { nome: "OROCHI + 9444 CONQUISTADORES", codigo: 'gAAMAw0DDgMNAwwDDQQMBA4EAAUBBQwFDQUOBQAFEgoMCg0KDg0BBQgFDAUNBQ4FAAoQHg8eCQELChIKCAoCBQgFBwECBQEBAQEBAQEBAQEBAQEBAQEBAQEBAwEDAQMBAwEDAQEBAgECAQIBAgECAQEBAQECAQIBAgEBAQEBAgECAQ8B9ICAgDk0NDQgQ29ucXVpc3RhZG9yZXP0gICANA==' },
    { nome: "OROCHI + MODELO FULL 12.154", codigo: '' }
