      if (pr.length) {
        c.modelos = pr;
        var esc = n0Ler().modeloCi || pr[0].id;
        if (!pr.some(function (m) { return m.id === esc; })) { esc = pr[0].id; }
        c.regras = [{ grupo: '0', grupoNome: 'Todas as aldeias', modelo: esc }];
      }
