      // seletor Ataque/Defesa
      box.querySelectorAll('.seg span[data-modo]').forEach(function (s) { s.addEventListener('click', function () { var n = n0Ler(); n.recModo = s.getAttribute('data-modo'); n0Gravar(n); try { recGravar(n0RecCfg(n.recModo)); } catch (e) {} desenhar(); }); });
      // toggles
      box.querySelectorAll('.pill[data-tog]').forEach(function (b) { b.addEventListener('click', function () { var n = n0Ler(), k = b.getAttribute('data-tog'); n[k] = !n[k]; n0Gravar(n); desenhar(); }); });
