  /* ============================================================
     N9 — CONQUISTADORES E SIMILARES (preset de conquista de bárbaras)
     Mesma base da N0/N1, mas: Farm Hard (2x, 4 grupos), Construtor "Academia
     Conquistadores", Recrutador "Farm Conquistadores", Coletor Hard (2 min, raio 550),
     Pesquisa em Massa (todas as tropas), Cunhagem (todas as páginas · guardar 2 · 2 min)
     e Noblar Automático (ciclo 20s). Tudo pré-configurado; a pessoa pode ajustar.
  ============================================================ */
  function n9Chave() { return 'ork_n9_' + n0Mundo(); }
  function n9Ler() {
    var p = { farm: true, rec: true, ci: true, ger: true, coletor: true, pesq: true, cunhar: true, noblar: true, rodando: false };
    try { var c = JSON.parse(localStorage.getItem(n9Chave()) || 'null'); if (c && typeof c === 'object') { for (var k in c) { p[k] = c[k]; } } } catch (e) {}
    return p;
  }
  function n9Gravar(c) { try { localStorage.setItem(n9Chave(), JSON.stringify(c)); } catch (e) {} }
