  /* ============================================================
     PROTEÇÃO GERAL DAS FERRAMENTAS (v83)
     - Se uma ferramenta der erro ao abrir, a janela quebrada é removida da tela
       (não fica presa) e aparece um aviso com: Tentar de novo / Limpar
       configurações e tentar / Copiar erro (pra mandar pro suporte).
     - Se o painel chegar numa tela diferente da esperada, avisa o motivo em vez
       de sumir em silêncio.
  ============================================================ */
  function orkChavesDaFerramenta(id) {
    var w = (window.game_data && game_data.world) || '';
    var local = {
      farmar: ['fh_cl_minimo', 'fh_cp_minimo', 'fh_recurso_minimo', 'fh_ritmo_humano', 'fh_prioriza_rica', 'fh_por_visita', 'fh_minimizado', 'Alvos_Muralha'],
      farmdormindo: ['ork_dormindo_cfg', 'ork_fh_normal_backup', 'ork_retomar_dormindo'],
      ataque: ['ork_loop_ataque_config', 'coordsRes', 'coordsIds'],
      rename: ['ork_renomeador_config'],
      barbaras: ['orkBarbList_Settings'],
      coletorfarm: ['fmMapLA_Settings'],
      cunhar: ['ork_cunhar_config', 'ork_cunhar_from', 'ork_cunhar_regras'],
      keypress: ['ork_keypress_config', 'ork_keypress_trava'],
      balanceador: ['ork_balanceador', 'ork_balanceador_trava'],
      gerente: ['ork_gerente', 'ork_gerente_trava', 'ork_gerente_catalogo_' + w, 'ork_gerente_url_tropas_' + w],
      nobrebb: ['ork_nobre_mapa_' + w, 'ork_nobre_maxdist_' + w, 'ork_nobre_trava'],
      noblaplayer: ['ork_noblap_trava'],
      pesqmassa: ['ork_pesqmassa_' + w],
      construcao: ['ork_construcao_' + w, 'ork_cr_max_' + w],
      recacademia: ['ork_recacademia_' + w],
      etiquetador: ['ork_etiquetador_' + w, 'ork_etiquetador_' + w + '_trava'],
      snipe: ['ork_snipe_' + w, 'ork_snipe_' + w + '_trava']
    };
    var sessao = { auto247: ['ork_auto247', 'ork_auto247_preset', 'ork_auto247_atk'], nobrebb: ['ork_nobre_' + w], noblaplayer: ['ork_noblap_' + w] };
    return { local: local[id] || [], sessao: sessao[id] || [] };
  }
  function orkLimparConfigFerramenta(id) {
    var ch = orkChavesDaFerramenta(id), n = 0;
    ch.local.forEach(function (k) { try { if (localStorage.getItem(k) !== null) { localStorage.removeItem(k); n++; } } catch (e) {} });
    ch.sessao.forEach(function (k) { try { if (sessionStorage.getItem(k) !== null) { sessionStorage.removeItem(k); n++; } } catch (e) {} });
    console.log('[OROCHIKING] Configurações de "' + id + '" limpas (' + n + ' item(ns)).');
    return n;
  }
  function orkTextoDoErro(f, err) {
    var gd = window.game_data || {};
    var linhas = [
      'OROCHIKING Versão ' + (window.__ORK_VERSAO__ || '?') + ' — ' + (f ? f.nome : '?'),
      'Tela: screen=' + gd.screen + ' mode=' + gd.mode + ' | mundo ' + gd.world + ' | premium: ' + (gd.player ? gd.player.premium : '?'),
      'Erro: ' + (err && err.message ? err.message : String(err))
    ];
    if (err && err.stack) { linhas.push(String(err.stack).split('\n').slice(0, 6).join('\n')); }
    var outros = (window.__ORK_ERROS__ || []).slice(-5);
    if (outros.length) {
      linhas.push('Últimos erros da página:');
      outros.forEach(function (x) { linhas.push('- ' + x.hora + ' ' + x.msg); });
    }
    return linhas.join('\n');
  }
  function orkCopiar(texto, botao) {
    function ok() { if (botao) { var t = botao.textContent; botao.textContent = '✔ Copiado!'; setTimeout(function () { botao.textContent = t; }, 1500); } }
    try { navigator.clipboard.writeText(texto).then(ok, function () { reserva(); }); } catch (e) { reserva(); }
    function reserva() {
      try { var ta = document.createElement('textarea'); ta.value = texto; ta.style.cssText = 'position:fixed;opacity:0'; document.body.appendChild(ta); ta.select(); document.execCommand('copy'); ta.remove(); ok(); }
      catch (e) { prompt('Copie o erro abaixo:', texto); }
    }
  }
  // Aviso no topo da tela. botoes = [{texto, principal, acao}]
  function orkAvisoFerramenta(titulo, mensagem, botoes) {
    var velho = document.getElementById('ork-aviso-ferramenta');
    if (velho) { velho.remove(); }
    var caixa = document.createElement('div');
    caixa.id = 'ork-aviso-ferramenta';
    caixa.style.cssText = 'position:fixed;top:14px;left:50%;transform:translateX(-50%);background:linear-gradient(165deg,rgba(26,26,26,.98),rgba(8,8,8,.99));' +
      'border:1px solid #8a3a1a;border-radius:12px;padding:12px 14px;z-index:2147483601;width:340px;max-width:calc(100vw - 20px);' +
      'font-family:"Segoe UI",Arial,sans-serif;color:#eee;box-shadow:0 14px 34px rgba(0,0,0,.75),0 0 0 3px rgba(255,107,107,.15)';
    var topo = document.createElement('div');
    topo.style.cssText = 'display:flex;align-items:center;gap:6px;margin-bottom:6px';
    var t = document.createElement('span');
    t.style.cssText = 'flex:1;font-weight:800;color:#ffb347;font-size:12.5px';
    t.textContent = titulo;
    var x = document.createElement('span');
    x.textContent = '×'; x.title = 'Fechar';
    x.style.cssText = 'cursor:pointer;color:#888;font-weight:800;font-size:16px';
    x.addEventListener('click', function () { caixa.remove(); });
    topo.appendChild(t); topo.appendChild(x);
    var msg = document.createElement('div');
    msg.style.cssText = 'font-size:11.5px;color:#ccc;line-height:1.45;margin-bottom:9px;white-space:pre-line';
    msg.textContent = mensagem;
    var linha = document.createElement('div');
    linha.style.cssText = 'display:flex;gap:6px;flex-wrap:wrap';
    botoes.forEach(function (b) {
      var el = document.createElement('button');
      el.type = 'button';
      el.textContent = b.texto;
      el.style.cssText = 'flex:1;min-width:90px;border-radius:7px;padding:7px 8px;cursor:pointer;font-weight:800;font-size:11px;font-family:inherit;' +
        (b.principal ? 'background:linear-gradient(100deg,#e8ac0a,#ffdc63);color:#141200;border:none' : 'background:#232323;color:#FFC400;border:1px solid #3a3a3a');
      el.addEventListener('click', function () { b.acao(el, caixa); });
      linha.appendChild(el);
    });
    caixa.appendChild(topo); caixa.appendChild(msg); caixa.appendChild(linha);
    document.body.appendChild(caixa);
    return caixa;
  }
  function orkErroFerramenta(f, err) {
    var temConfig = orkChavesDaFerramenta(f.id);
    var botoes = [{ texto: '↻ Tentar de novo', principal: true, acao: function (el, cx) { cx.remove(); orkExecutar(f); } }];
    if (temConfig.local.length || temConfig.sessao.length) {
      botoes.push({ texto: '🧹 Limpar configurações e tentar', acao: function (el, cx) {
        if (!confirm('Apagar as configurações salvas de "' + f.nome + '" neste navegador e abrir de novo?\n\nIsso volta os ajustes dela pro padrão. As outras ferramentas não mudam.')) { return; }
        orkLimparConfigFerramenta(f.id); cx.remove(); orkExecutar(f);
      } });
    }
    botoes.push({ texto: '📋 Copiar erro', acao: function (el) { orkCopiar(orkTextoDoErro(f, err), el); } });
    orkAvisoFerramenta('⚠ ' + f.nome + ' não abriu',
      (err && err.message ? err.message : String(err)) + '\n\nSe continuar, clique em "Copiar erro" e mande pro suporte.', botoes);
  }
  // Roda a ferramenta; se quebrar ao abrir, tira da tela o que ficou pela metade e avisa
  /* v108: BOLINHAS NO CANTO ESQUERDO — as bolinhas ligadas ficam encostadas à esquerda, uma do lado da
     outra, sem buracos (antes cada uma tinha lugar fixo e as últimas caíam no meio da tela).
     O Coletor Hard continua no canto direito. */
  (function bolinhasNoCanto() {
    var IDS = ['ork-painel-bolinha', 'ork-cunhar-bolinha', 'ork-kp-bolinha', 'ork-auto-bolinha', 'ork-bal-bolinha', 'ork-ger-bolinha', 'ork-nob-bolinha',
      'ork-npl-bolinha', 'ork-fh-bolinha', 'ork-ra-bolinha', 'ork-etq-bolinha', 'ork-snp-bolinha', 'ork-ren-bolinha', 'ork-aa-bolinha', 'ork-col-bolinha', 'ork-mpp-bolinha', 'ork-rec-bolinha', 'ork-ci-bolinha'];
    // v110: uma ACIMA da outra no canto esquerdo, já no lugar certo ao aparecer (sem passar pelo meio)
    function arrumar() {
      var y = 20;
      IDS.forEach(function (id) {
        var b = document.getElementById(id);
        if (!b || b.style.display === 'none') { return; }
        if (b.style.left !== '10px') { b.style.left = '10px'; }
        if (b.style.bottom !== y + 'px') { b.style.bottom = y + 'px'; }
        if (b.style.right) { b.style.right = ''; }
        y += 62;
      });
      // v117: cartão do Saque do dia do KeyPress fica AO LADO da bolinha ⌨️ (à direita), na mesma altura — não cobre as outras bolinhas
      var kp = document.getElementById('ork-kp-bolinha'), rk = document.getElementById('ork-kp-rank');
      if (kp && rk) { var by = (parseInt(kp.style.bottom, 10) || 20) - 8; if (rk.style.bottom !== by + 'px') { rk.style.bottom = by + 'px'; } if (rk.style.left !== '72px') { rk.style.left = '72px'; } }
    }
    try {
      // arruma no mesmo instante em que uma bolinha é colocada na página (antes de aparecer na tela)
      new MutationObserver(function (muts) { for (var i = 0; i < muts.length; i++) { for (var j = 0; j < muts[i].addedNodes.length; j++) { var n = muts[i].addedNodes[j]; if (n && n.id && (IDS.indexOf(n.id) !== -1 || n.id === 'ork-kp-rank')) { arrumar(); return; } } } }).observe(document.body, { childList: true });
      setInterval(arrumar, 800); arrumar();
    } catch (e) {}
  })();

  /* v111: COLETOR HARD — garante que a janela abra DE VERDADE e inteira dentro da tela, tanto pelo
     painel quanto pela bolinha (mesmo que um script antigo/separado do Coletor tenha sido carregado antes). */
  function orkColetorGarantirVisivel(abrir) {
    try {
      var h = document.getElementById('orochiking_host'), r = h && (h.shadowRoot || h), p = r && r.getElementById ? r.getElementById('painel') : null;
      if (!p) { console.warn('[OROCHIKING] Coletor Hard: janela não encontrada nesta página.'); return false; }
      if (abrir) { p.classList.remove('oculto'); }
      if (p.classList.contains('oculto')) { return true; }
      h.style.zIndex = '2147483000'; h.style.display = ''; h.style.visibility = '';
      var b = p.getBoundingClientRect(), fora = b.width < 50 || b.right < 60 || b.bottom < 60 || b.left > window.innerWidth - 60 || b.top > window.innerHeight - 60 || b.top < 0 || b.bottom > window.innerHeight + 2;
      if (fora) {
        p.style.left = ''; p.style.top = ''; p.style.right = '20px'; p.style.bottom = '84px';
        try { var k = 'orochiking_cfg_' + location.host, c = JSON.parse(localStorage.getItem(k) || '{}'); c.pos = null; c.aberto = true; localStorage.setItem(k, JSON.stringify(c)); } catch (e) {}
        console.log('[OROCHIKING] Coletor Hard: a janela estava fora da tela — trouxe de volta.');
      }
      return true;
    } catch (e) { console.warn('[OROCHIKING] Coletor Hard:', e); return false; }
  }
  // clique na bolinha do Coletor Hard: depois que ela abre, confere se a janela ficou visível
  try {
    document.addEventListener('click', function (ev) {
      var cam = ev.composedPath ? ev.composedPath() : [];
      for (var i = 0; i < cam.length; i++) { if (cam[i] && cam[i].id === 'bolha') { setTimeout(function () { orkColetorGarantirVisivel(false); }, 60); return; } }
    }, true);
  } catch (e) {}

  var ORK_ATALHO_PERFIL = 'ork_atalho_perfil', ORK_ATALHO_RENOMEAR = 'ork_atalho_renomear', ORK_ATALHO_ATAQUE = 'ork_atalho_ataque';
  var ORK_AUTO_BARB = 'ork_barb_auto', ORK_AUTO_CANCELAR = 'ork_cancelar_auto', ORK_AUTO_COLETORFARM = 'ork_coletorfarm_auto';
  /* v112: ATALHO DO RENOMEADOR NO COMBINADO — depois de usar uma vez pelo painel, a tela Combinado
     mostra ✏️ Renomear e ⏹ Parar do lado de "Aldeias por página" (sem voltar no painel). */
  function orkAtalhoRenomear() {
    try {
      if (!(window.game_data && game_data.screen === 'overview_villages' && game_data.mode === 'combined')) { return; }
      var temRen = localStorage.getItem(ORK_ATALHO_RENOMEAR) === '1', temAtk = localStorage.getItem(ORK_ATALHO_ATAQUE) === '1';
      if ((!temRen && !temAtk) || document.getElementById('ork-atalho-ren')) { return; }
      var inp = document.querySelector('input[name="page_size"]'), ancora = inp ? (inp.form ? (inp.form.querySelector('input[type="submit"], button, .btn') || inp) : inp) : null;
      var box = document.createElement('span'); box.id = 'ork-atalho-ren';
      box.style.cssText = 'display:inline-flex;gap:5px;align-items:center;margin-left:8px;vertical-align:middle';
      var bt = 'border:none;border-radius:6px;padding:4px 10px;cursor:pointer;font-weight:800;font-size:11.5px;font-family:"Segoe UI",Arial,sans-serif';
      box.innerHTML = (temAtk ? '<button type="button" id="ork-atk-ir" style="' + bt + ';background:linear-gradient(100deg,#FFB800,#FFDD55);color:#141200" title="Abre o Atacar/Apoiar aqui mesmo (mesmo do painel), com os comandos salvos">⚔️ Atacar/Apoiar</button>' : '') +
        (temRen ? '<button type="button" id="ork-ren-ir" style="' + bt + ';background:linear-gradient(100deg,#FFB800,#FFDD55);color:#141200" title="Abre o Renomeador Hard (mesmo do painel)">✏️ Renomear</button>' +
        '<button type="button" id="ork-ren-parar" style="' + bt + ';background:#2a1010;color:#ff6b6b;border:1px solid #4a1c1c" title="Para o Renomeador e fecha a janela dele">⏹ Parar</button>' : '') +
        '<span id="ork-ren-x" style="color:#8a6a3a;cursor:pointer;font-weight:800;font-size:13px" title="Tirar estes botões (voltam quando usar a ferramenta pelo painel)">&times;</span>';
      // v115: vai pro TOPO da lista (logo acima da tabela das aldeias, abaixo da paginação), mais visível
      var tabela = document.getElementById('combined_table') || document.querySelector('#paged_view_content table.vis, table.overview_table');
      if (tabela && tabela.parentNode) {
        var faixa = document.createElement('div'); faixa.id = 'ork-atalho-ren-faixa';
        faixa.style.cssText = 'display:flex;justify-content:center;align-items:center;gap:6px;margin:4px 0 6px;padding:5px 8px;background:#1a1a1a;border:1px solid #3a3a3a;border-radius:8px';
        box.style.marginLeft = '0';
        faixa.appendChild(box); tabela.parentNode.insertBefore(faixa, tabela);
        box.querySelector('#ork-ren-x') && (box.querySelector('#ork-ren-x').style.color = '#a08850');
      }
      else if (ancora && ancora.parentNode) { ancora.parentNode.insertBefore(box, ancora.nextSibling); }
      else { box.style.cssText += ';position:fixed;top:70px;right:14px;z-index:99990;background:#1a1a1a;padding:6px 8px;border-radius:10px;border:1px solid #3a3a3a'; document.body.appendChild(box); }
      var bAtk = box.querySelector('#ork-atk-ir');
      if (bAtk) { bAtk.addEventListener('click', function (e) { e.preventDefault(); var f = FERRAMENTAS_POR_ID.ataque; if (f) { orkExecutar(f); } }); }
      var bRen = box.querySelector('#ork-ren-ir');
      if (bRen) { bRen.addEventListener('click', function (e) { e.preventDefault(); var f = FERRAMENTAS_POR_ID.rename; if (f) { orkExecutar(f); } }); }
      if (box.querySelector('#ork-ren-parar')) box.querySelector('#ork-ren-parar').addEventListener('click', function (e) {
        e.preventDefault();
        var st = document.getElementById('rh-stop'); if (st && !st.disabled) { st.click(); }
        var pp = document.getElementById('rh-popup'); if (pp) { pp.style.display = 'none'; }
      });
      box.querySelector('#ork-ren-x').addEventListener('click', function () { try { localStorage.removeItem(ORK_ATALHO_RENOMEAR); localStorage.removeItem(ORK_ATALHO_ATAQUE); } catch (e) {} var fx = document.getElementById('ork-atalho-ren-faixa'); if (fx) { fx.remove(); } else { box.remove(); } });
    } catch (e) {}
  }
  setTimeout(orkAtalhoRenomear, 500);

  /* v214 — BOTÕES/ABERTURA AUTOMÁTICA QUANDO A FERRAMENTA ESTÁ ATIVA
     Mesma ideia dos atalhos do Combinado (⚔️/✏️), agora em outras telas:
     • Agendador ligado → botão 🗓️ Agendar comandos na Praça de Reunião.
     • Coletor de Bárbaras usado uma vez → abre sozinho sempre que o Mapa abrir.
     • Cancelar Recrutamento usado uma vez → botão 🚫 no topo da Produção.
     • Etiquetador ligado → ao abrir os Comandos, etiqueta na hora (além do automático por trás). */
  function orkAtalhoAgendador() {
    try {
      if (!(window.game_data && game_data.screen === 'place')) { return; }
      var faixaAnt = document.getElementById('ork-atalho-ag-faixa');
      if (!agLer().ativo) { if (faixaAnt) { faixaAnt.remove(); } return; }
      if (faixaAnt) { return; }
      var faixa = document.createElement('div'); faixa.id = 'ork-atalho-ag-faixa';
      faixa.style.cssText = 'display:flex;justify-content:center;align-items:center;gap:6px;margin:4px 0 6px;padding:5px 8px;background:#1a1a1a;border:1px solid #3a3a3a;border-radius:8px';
      var bt = 'border:none;border-radius:6px;padding:4px 12px;cursor:pointer;font-weight:800;font-size:11.5px;font-family:"Segoe UI",Arial,sans-serif';
      faixa.innerHTML = '<button type="button" id="ork-ag-ir" style="' + bt + ';background:linear-gradient(100deg,#FFB800,#FFDD55);color:#141200" title="Abre o Agendador de comandos (mesmo do painel), com a fila salva">🗓️ Agendar comandos</button>';
      var alvo = document.getElementById('content_value') || document.querySelector('form');
      if (alvo && alvo.firstChild) { alvo.insertBefore(faixa, alvo.firstChild); }
      else if (alvo) { alvo.appendChild(faixa); }
      else { faixa.style.cssText += ';position:fixed;top:70px;right:14px;z-index:99990'; document.body.appendChild(faixa); }
      faixa.querySelector('#ork-ag-ir').addEventListener('click', function (e) { e.preventDefault(); rodarAgendador(); });
    } catch (e) {}
  }
  function orkAtalhoCancelar() {
    try {
      if (!(window.game_data && game_data.mode === 'prod' && document.getElementById('production_table'))) { return; }
      var faixaAnt = document.getElementById('ork-atalho-cn-faixa');
      if (localStorage.getItem(ORK_AUTO_CANCELAR) !== '1') { if (faixaAnt) { faixaAnt.remove(); } return; }
      if (faixaAnt) { return; }
      var faixa = document.createElement('div'); faixa.id = 'ork-atalho-cn-faixa';
      faixa.style.cssText = 'display:flex;justify-content:center;align-items:center;gap:6px;margin:4px 0 6px;padding:5px 8px;background:#1a1a1a;border:1px solid #3a3a3a;border-radius:8px';
      var bt = 'border:none;border-radius:6px;padding:4px 12px;cursor:pointer;font-weight:800;font-size:11.5px;font-family:"Segoe UI",Arial,sans-serif';
      faixa.innerHTML = '<button type="button" id="ork-cn-ir" style="' + bt + ';background:linear-gradient(100deg,#ff6b6b,#ff9a9a);color:#2a0000" title="Cancela o recrutamento (quartel, estábulo e oficina) de todas as aldeias, agora">🚫 Cancelar recrutamento</button>' +
        '<span id="ork-cn-x" style="color:#a08850;cursor:pointer;font-weight:800;font-size:13px" title="Tirar este botão (volta quando usar pelo painel)">&times;</span>';
      var tabela = document.getElementById('production_table');
      if (tabela && tabela.parentNode) { tabela.parentNode.insertBefore(faixa, tabela); }
      else { faixa.style.cssText += ';position:fixed;top:70px;right:14px;z-index:99990'; document.body.appendChild(faixa); }
      faixa.querySelector('#ork-cn-ir').addEventListener('click', function (e) { e.preventDefault(); var f = FERRAMENTAS_POR_ID.cancelar; if (f) { orkExecutar(f); } });
      faixa.querySelector('#ork-cn-x').addEventListener('click', function () { try { localStorage.removeItem(ORK_AUTO_CANCELAR); } catch (e) {} faixa.remove(); });
    } catch (e) {}
  }
  // abrir sozinho no mapa: Coletar Bárbaras (Barb Finder) E Coletor BB Assistente — cada um com seu próprio liga/desliga
  var ORK_MAPA_AUTO = [
    { flag: ORK_AUTO_BARB,        cont: 'orkBarbList_popup_container', cross: 'orkBarbList_popup_cross', feito: '__orkBarbAutoFeito',        esperaMapa: true,  nome: 'Coletor de Bárbaras',  rodar: function () { rodarBarbaras(); } },
    { flag: ORK_AUTO_COLETORFARM, cont: 'fmMapLA_popup_container',     cross: 'fmMapLA_popup_cross',     feito: '__orkColetorFarmAutoFeito', esperaMapa: false, nome: 'Coletor BB Assistente', rodar: function () { rodarColetorFarm(); } }
  ];
  function orkMapaAuto() {
    try {
      if (!(window.game_data && game_data.screen === 'map')) { return; }
      ORK_MAPA_AUTO.forEach(function (t) {
        if (localStorage.getItem(t.flag) !== '1') { return; }
        if (document.getElementById(t.cont)) { return; }        // já aberto
        if (window[t.feito]) { return; }                        // uma vez por carregamento
        if (t.esperaMapa && (typeof TWMap === 'undefined' || !TWMap || !TWMap.villages)) { setTimeout(orkMapaAuto, 800); return; }  // espera o mapa carregar
        window[t.feito] = true;
        try { t.rodar(); } catch (e) {}
      });
    } catch (e) {}
  }
  // fechar a janela pergunta se para de abrir sozinho no mapa
  try {
    document.addEventListener('click', function (ev) {
      if (!ev.target) { return; }
      ORK_MAPA_AUTO.forEach(function (t) {
        if (localStorage.getItem(t.flag) !== '1') { return; }
        var al = ev.target.id === t.cross || (ev.target.closest && ev.target.closest('#' + t.cross));
        if (!al) { return; }
        setTimeout(function () { if (confirm('Parar de abrir o ' + t.nome + ' sozinho ao abrir o mapa?\n(pra voltar, é só abrir pelo painel)')) { try { localStorage.removeItem(t.flag); } catch (e) {} } }, 50);
      });
    }, true);
  } catch (e) {}
  function orkEtqAuto() {
    try {
      if (!etqLer().ativo || !etqNaTela()) { return; }
      if (window.__orkEtqAutoFeito) { return; }
      window.__orkEtqAutoFeito = true;
      etqMostrarBolinha();
      etqRodarUmaVez(true);   // etiqueta na hora ao abrir os Comandos (manual pula a trava)
    } catch (e) {}
  }
  setTimeout(orkAtalhoAgendador, 500);
  setTimeout(orkAtalhoCancelar, 500);
  setTimeout(orkMapaAuto, 500);
  setTimeout(orkMapaAuto, 1300);
  setTimeout(orkEtqAuto, 1500);
  try { setInterval(function () { orkAtalhoAgendador(); orkAtalhoCancelar(); }, 2000); } catch (e) {}

  function orkExecutar(f) {
    // v107: usou Perfil/Ocultar uma vez → os atalhos aparecem sozinhos em todo perfil de jogador
    if (f && (f.id === 'perfil' || f.id === 'ocultar')) { try { localStorage.setItem(ORK_ATALHO_PERFIL, '1'); } catch (e) {} }
    if (f && f.id === 'rename') { try { localStorage.setItem(ORK_ATALHO_RENOMEAR, '1'); } catch (e) {} setTimeout(orkAtalhoRenomear, 300); }
    if (f && f.id === 'ataque') { try { localStorage.setItem(ORK_ATALHO_ATAQUE, '1'); } catch (e) {} } // v115: botão ⚔️ Atacar no Combinado
    if (f && f.id === 'barbaras') { try { localStorage.setItem(ORK_AUTO_BARB, '1'); } catch (e) {} window.__orkBarbAutoFeito = true; } // v214: abre sozinho no mapa
    if (f && f.id === 'coletorfarm') { try { localStorage.setItem(ORK_AUTO_COLETORFARM, '1'); } catch (e) {} window.__orkColetorFarmAutoFeito = true; } // v215: BB Assistente abre sozinho no mapa
    if (f && f.id === 'cancelar') { try { localStorage.setItem(ORK_AUTO_CANCELAR, '1'); } catch (e) {} setTimeout(orkAtalhoCancelar, 300); } // v214: botão 🚫 na Produção
    var antes = new Set(Array.prototype.slice.call(document.body.children));
    try {
      f.rodar();
      return true;
    } catch (err) {
      Array.prototype.slice.call(document.body.children).forEach(function (el) {
        if (antes.has(el) || /^ork-(captcha|novidade|aviso-ferramenta)/.test(el.id || '')) { return; }
        try { el.remove(); } catch (e) {}
      });
      console.error('[OROCHIKING] ' + f.nome + ' não abriu:', err);
      orkRegistrarErro((f.nome + ': ') + (err && err.message ? err.message : err));
      orkErroFerramenta(f, err);
      return false;
    }
  }
  function orkMotivoTelaErrada(f) {
    var gd = window.game_data || {};
    var semPremium = gd.player && gd.player.premium === false;
    var m = f.telaErrada || ('Esta não é a tela que o ' + f.nome + ' precisa.');
    if (semPremium && /overview_villages/.test(DESTINOS[f.destino] || '')) {
      m += '\n\nSua conta está SEM Conta Premium — sem ela o jogo não mostra essa visualização.';
    }
    return m + '\n\n(Tela atual: screen=' + gd.screen + ', mode=' + gd.mode + ')';
  }
  function orkAvisarTelaErrada(f) {
    orkAvisoFerramenta('⚠ ' + f.nome + ' não abriu nesta tela', orkMotivoTelaErrada(f), [
      { texto: 'Abrir mesmo assim', principal: true, acao: function (el, cx) { cx.remove(); orkExecutar(f); } },
      { texto: '📋 Copiar detalhes', acao: function (el) { orkCopiar(orkTextoDoErro(f, new Error('tela errada: ' + orkMotivoTelaErrada(f).replace(/\n+/g, ' '))), el); } }
    ]);
  }

  /* ===== v241: DEMOLIR DE MURALHAS =====
     Manda a tropa escolhida (ex.: 250 Bárbaro + 25 Ariete + 1 Explorador) pras bárbaras num raio em volta
     de CADA aldeia sua, pra derrubar a muralha delas e melhorar o farm.
     Alvos: lidos do Assistente de Saque (mesma fonte do Farm Hard). Um ataque por alvo por ciclo,
     sempre da aldeia sua mais perto. Envio pela tela de ataque do próprio jogo (place). */
  var DM_NOMES = { spear: 'Lanceiro', sword: 'Espadachim', axe: 'Bárbaro', archer: 'Arqueiro', spy: 'Explorador', light: 'Cav. leve', marcher: 'Arq. a cavalo', heavy: 'Cav. pesada', ram: 'Ariete', catapult: 'Catapulta', knight: 'Paladino', militia: 'Milícia' };
  var DM_ORDEM = ['spear', 'sword', 'axe', 'archer', 'spy', 'light', 'marcher', 'heavy', 'ram', 'catapult', 'knight', 'militia'];
  var DM_PADRAO = { raio: 10, intervaloMin: 30, velocidade: 1, maxPorCiclo: 60, porAlvo: 1, catRandom: false, tropas: { axe: 250, ram: 25, spy: 1 } };
  var dmTimer = null, dmRodando = false, dmParando = false;
  function dmChave() { return 'ork_demolir_' + ((window.game_data && game_data.world) || ''); }
  function dmLer() {
    var c = { ativo: false, raio: DM_PADRAO.raio, intervaloMin: DM_PADRAO.intervaloMin, velocidade: DM_PADRAO.velocidade, maxPorCiclo: DM_PADRAO.maxPorCiclo, porAlvo: DM_PADRAO.porAlvo, catRandom: DM_PADRAO.catRandom, tropas: JSON.parse(JSON.stringify(DM_PADRAO.tropas)), ciclos: 0 };
    try {
      var s = JSON.parse(localStorage.getItem(dmChave()) || 'null');
      if (s && typeof s === 'object') { for (var k in s) { if (k !== 'tropas') { c[k] = s[k]; } } if (s.tropas && typeof s.tropas === 'object') { c.tropas = s.tropas; } }
    } catch (e) {}
    return c;
  }
  function dmGravar(c) { try { localStorage.setItem(dmChave(), JSON.stringify(c)); } catch (e) {} }
  function dmLog(t) {
    try { console.log('[OROCHIKING] Demolir: ' + t); } catch (e) {}
    var el = document.getElementById('dm-log');
    if (el) { var l = document.createElement('div'); l.textContent = new Date().toLocaleTimeString('pt-BR') + '  ' + t; el.insertBefore(l, el.firstChild); while (el.children.length > 60) { el.removeChild(el.lastChild); } }
  }
  function dmStatus(t) { var el = document.getElementById('dm-status'); if (el) { el.textContent = t; } var b = document.getElementById('ork-dm-bolinha'); if (b) { b.textContent = '🧱 Demolir: ' + t; } }
  // v245: bolinha na tela (igual às outras automações) — mostra que o demolidor está rodando/esperando
  function dmBolinha(on) {
    var el = document.getElementById('ork-dm-bolinha');
    if (!on) { if (el) { el.remove(); } return; }
    if (!el) {
      el = document.createElement('div'); el.id = 'ork-dm-bolinha';
      el.style.cssText = 'position:fixed;left:14px;bottom:14px;z-index:2147483000;background:#141200;color:#FFC400;border:1px solid #8a6d00;border-radius:20px;padding:6px 12px;font:700 12px "Segoe UI",Arial,sans-serif;cursor:pointer;box-shadow:0 4px 14px rgba(0,0,0,.6)';
      el.title = 'Demolir de Muralhas: clique pra abrir';
      el.addEventListener('click', function () { dmAbrir(); });
      document.body.appendChild(el);
    }
    el.textContent = '🧱 Demolir: ' + ((document.getElementById('dm-status') || {}).textContent || 'ativo');
  }
  function dmUnidades() { var u = (window.game_data && game_data.units) || []; return DM_ORDEM.filter(function (x) { return u.indexOf(x) !== -1; }); }
  function dmCoord(s) { var m = String(s || '').match(/(\d{1,3})\|(\d{1,3})/); return m ? { x: +m[1], y: +m[2], k: m[1] + '|' + m[2] } : null; }
  function dmDoc(html) { return new DOMParser().parseFromString(html, 'text/html'); }
  var DM_ID = Math.random().toString(36).slice(2);
  function dmSouDono() {
    var k = 'ork_dm_dono_' + ((window.game_data && game_data.world) || '');
    var d = null; try { d = JSON.parse(localStorage.getItem(k) || 'null'); } catch (e) {}
    if (d && d.id !== DM_ID && Date.now() - d.t < 90000) { return false; }
    try { localStorage.setItem(k, JSON.stringify({ id: DM_ID, t: Date.now() })); } catch (e) {}
    return true;
  }
  function dmCaptcha(doc) { return !!doc.querySelector('#bot_check, [id^="bot_check"]'); }
  function dmErro(doc) { var e = doc.querySelector('.error_box, #error, .error'); return e ? (e.textContent || '').replace(/\s+/g, ' ').trim() : ''; }
  // formulário -> corpo (campos ativos, como o navegador enviaria)
  function dmCorpo(form) {
    var corpo = new URLSearchParams();
    Array.prototype.slice.call(form.elements).forEach(function (el) {
      if (!el.name || el.disabled) { return; }
      if (el.type === 'submit' || el.type === 'button' || el.type === 'image' || el.type === 'file') { return; }
      if ((el.type === 'checkbox' || el.type === 'radio') && !el.checked) { return; }
      corpo.append(el.name, el.value);
    });
    return corpo;
  }
  // minhas aldeias com coordenadas (mesma leitura da Produção que as outras ferramentas usam)
  async function dmMinhasAldeias() {
    var dados = await balDadosProducao('0'), out = [];
    (dados.list_production || []).forEach(function (v) { var c = dmCoord(v.coord || v.name); if (c && v.id) { out.push({ id: String(v.id), x: c.x, y: c.y, k: c.k }); } });
    return out;
  }
  // alvos: bárbaras do Assistente de Saque (lista paginada), sem as suas aldeias
  async function dmAlvos(minhasKeys) {
    var mapa = new Map();
    var base = '/game.php?village=' + game_data.village.id + '&screen=am_farm&order=distance&dir=asc&Farm_page=';
    for (var p = 0; p < 50 && !dmParando; p++) {
      var antes = mapa.size;
      var doc = dmDoc(await (await fetch(base + p, { credentials: 'include' })).text());
      doc.querySelectorAll('#plunder_list tr[id^="village_"]').forEach(function (row) {
        var link = row.querySelector('a[href*="screen=report&mode=all&view="]');
        var c = link && dmCoord(link.textContent);
        if (c && !minhasKeys.has(c.k)) { mapa.set(c.k, c); }
      });
      if (mapa.size === antes) { break; }
      await gerEsperar(gerEntre(300, 600));
    }
    return Array.from(mapa.values());
  }
  // um ataque: abre a tela de ataque da aldeia de origem, põe as tropas, confirma (2 passos, como o jogo)
  async function dmEnviar(origem, alvo, tropas, catRandom) {
    var base = '/game.php?village=' + origem + '&screen=place';
    var doc1 = dmDoc(await (await fetch(base + '&x=' + alvo.x + '&y=' + alvo.y, { credentials: 'include' })).text());
    if (dmCaptcha(doc1)) { return { captcha: true }; }
    var f1 = doc1.querySelector('#command-data-form') || doc1.querySelector('form[action*="screen=place"]');
    if (!f1) { return { erro: 'tela de ataque não abriu' }; }
    var corpo = dmCorpo(f1);
    corpo.set('x', alvo.x); corpo.set('y', alvo.y);
    dmUnidades().forEach(function (u) { corpo.set(u, String(parseInt(tropas[u], 10) || 0)); });
    if (catRandom && (parseInt(tropas.catapult, 10) || 0) > 0) {
      var opcCat = Array.prototype.slice.call(doc1.querySelectorAll('select[name="catapult_target"] option')).map(function (o) { return o.value; }).filter(function (v) { return v; });
      if (opcCat.length) { corpo.set('catapult_target', opcCat[Math.floor(Math.random() * opcCat.length)]); }
    }
    var botaoAtaque = f1.querySelector('#target_attack, input[name="attack"]');
    corpo.set((botaoAtaque && botaoAtaque.name) || 'attack', (botaoAtaque && botaoAtaque.value) || 'Atacar');
    var url1 = new URL(f1.getAttribute('action') || base, location.href).href;
    var doc2 = dmDoc(await (await fetch(url1, { method: 'POST', credentials: 'include', headers: { 'content-type': 'application/x-www-form-urlencoded' }, body: corpo.toString() })).text());
    if (dmCaptcha(doc2)) { return { captcha: true }; }
    var f2 = doc2.querySelector('#command-data-form');
    if (!f2) { return { erro: dmErro(doc2) || 'confirmação não apareceu' }; }
    var corpo2 = dmCorpo(f2);
    var go = f2.querySelector('#troop_confirm_go, input[type="submit"]');
    if (go && go.name) { corpo2.set(go.name, go.value || '1'); }
    var url2 = new URL(f2.getAttribute('action') || url1, location.href).href;
    var doc3 = dmDoc(await (await fetch(url2, { method: 'POST', credentials: 'include', headers: { 'content-type': 'application/x-www-form-urlencoded' }, body: corpo2.toString() })).text());
    if (dmCaptcha(doc3)) { return { captcha: true }; }
    var e3 = dmErro(doc3);
    if (e3) { return { erro: e3 }; }
    return { ok: true };
  }
  // um ciclo: lê os alvos, escolhe a aldeia mais perto de cada um dentro do raio, manda 1 ataque por alvo
  async function dmCiclo() {
    if (dmRodando) { return; }
    var cfg = dmLer();
    if (!cfg.ativo) { return; }
    if (!window.game_data || !game_data.village) { dmLog('abra uma aldeia sua pra começar.'); return; }
    if (!dmSouDono()) { dmLog('outra aba está rodando o demolidor.'); return; }
    dmRodando = true; dmParando = false; dmBolinha(true);
    try {
      dmStatus('lendo aldeias e alvos...');
      var minhas = await dmMinhasAldeias();
      var minhasKeys = new Set(minhas.map(function (m) { return m.k; }));
      var alvos = await dmAlvos(minhasKeys);
      var porAlvo = Math.max(1, parseInt(cfg.porAlvo, 10) || 1);
      var fila = [];
      alvos.forEach(function (a) {
        var cands = [];
        minhas.forEach(function (m) { var d = Math.hypot(m.x - a.x, m.y - a.y); if (d <= cfg.raio) { cands.push({ origem: m.id, d: d }); } });
        cands.sort(function (p, q) { return p.d - q.d; });
        cands.slice(0, porAlvo).forEach(function (c) { fila.push({ origem: c.origem, alvo: a, d: c.d }); });
      });
      fila.sort(function (p, q) { return p.d - q.d; });
      fila = fila.slice(0, cfg.maxPorCiclo);
      dmLog(alvos.length + ' bárbaras lidas, ' + fila.length + ' dentro de ' + cfg.raio + ' campos de alguma aldeia sua.');
      var falhas = {}, enviados = 0;
      for (var i = 0; i < fila.length && !dmParando; i++) {
        if (!dmLer().ativo) { break; }
        while (window.__ORK_CAPTCHA_BLOQUEADO__) { await gerEsperar(gerEntre(3000, 5000)); }
        var it = fila[i];
        if (!dmSouDono()) { dmLog('outra aba assumiu o demolidor. Parando aqui.'); break; }
        if ((falhas[it.origem] || 0) >= 3) { continue; }
        dmStatus('atacando ' + (i + 1) + '/' + fila.length);
        var r = await dmEnviar(it.origem, it.alvo, cfg.tropas, cfg.catRandom);
        if (r.captcha) { dmLog('captcha apareceu — resolva e ligue de novo.'); cfg.ativo = false; dmGravar(cfg); break; }
        if (r.erro) { falhas[it.origem] = (falhas[it.origem] || 0) + 1; dmLog(it.alvo.k + ' (de ' + it.origem + '): ' + r.erro); }
        else { enviados++; dmLog('✔ ataque em ' + it.alvo.k + ' saiu da aldeia ' + it.origem + '.'); }
        await gerEsperar(gerEntre(1500, 2500) / (parseFloat(cfg.velocidade) || 1));
      }
      cfg = dmLer();
      cfg.ciclos = (cfg.ciclos || 0) + 1;
      dmGravar(cfg);
      dmLog('ciclo ' + cfg.ciclos + ' terminou: ' + enviados + ' ataques enviados.');
      if (cfg.ativo && !dmParando) {
        var espera = Math.max(1, parseFloat(cfg.intervaloMin) || 30) * 60000;
        dmStatus('próximo ciclo em ' + Math.round(espera / 60000) + ' min');
        dmTimer = setTimeout(dmCiclo, espera);
      } else { dmStatus('Parado'); }
    } catch (e) {
      dmLog('erro: ' + (e && e.message ? e.message : e));
      dmStatus('Parado por erro');
    } finally { dmRodando = false; }
  }
  function dmParar() {
    var cfg = dmLer(); cfg.ativo = false; dmGravar(cfg);
    dmParando = true; if (dmTimer) { clearTimeout(dmTimer); dmTimer = null; }
    dmStatus('Parado'); dmLog('parado.'); dmBolinha(false);
  }
  function dmAtualizarUI() {
    var cfg = dmLer(), q = function (id) { return document.getElementById(id); };
    if (!q('dm-raio')) { return; }
    q('dm-raio').value = cfg.raio; q('dm-int').value = cfg.intervaloMin; q('dm-max').value = cfg.maxPorCiclo;
    q('dm-vel').value = String(cfg.velocidade);
    if (q('dm-por')) { q('dm-por').value = cfg.porAlvo || 1; q('dm-catrand').checked = !!cfg.catRandom; }
    document.querySelectorAll('#ork-dm-popup [data-u]').forEach(function (el) { el.value = parseInt((cfg.tropas || {})[el.getAttribute('data-u')], 10) || 0; });
  }
  function dmLerUI() {
    var q = function (id) { return document.getElementById(id); }, tropas = {};
    document.querySelectorAll('#ork-dm-popup [data-u]').forEach(function (el) { tropas[el.getAttribute('data-u')] = Math.max(0, parseInt(el.value, 10) || 0); });
    var cfg = dmLer();
    cfg.raio = Math.max(1, parseFloat(q('dm-raio').value) || DM_PADRAO.raio);
    cfg.intervaloMin = Math.max(1, parseFloat(q('dm-int').value) || DM_PADRAO.intervaloMin);
    cfg.maxPorCiclo = Math.max(1, parseInt(q('dm-max').value, 10) || DM_PADRAO.maxPorCiclo);
    cfg.velocidade = parseFloat(q('dm-vel').value) || 1;
    cfg.porAlvo = Math.max(1, parseInt(q('dm-por').value, 10) || 1);
    cfg.catRandom = !!q('dm-catrand').checked;
    cfg.tropas = tropas;
    return cfg;
  }
  // v245: solta a trava ao sair da página (senão a página nova achava que outra aba estava rodando)
  window.addEventListener('pagehide', function () {
    try { var kP = 'ork_dm_dono_' + ((window.game_data && game_data.world) || ''); var dP = JSON.parse(localStorage.getItem(kP) || 'null'); if (dP && dP.id === DM_ID) { localStorage.removeItem(kP); } } catch (e) {}
  });
  // v245: retoma sozinho ao carregar (como o agendador). Se a trava ainda estiver com outra página, tenta de novo a cada 10 s (até ~10 min).
  (function dmRetomarAuto(tent) {
    if (!(dmLer().ativo && window.game_data && game_data.village)) { return; }
    if (dmSouDono()) {
      dmBolinha(true); dmStatus('retomando...'); dmLog('retomando sozinho depois de recarregar a página.');
      setTimeout(dmCiclo, 5000);
      return;
    }
    dmBolinha(true); dmStatus('aguardando outra aba soltar o demolidor...');
    if (tent < 60) { setTimeout(function () { dmRetomarAuto(tent + 1); }, 10000); }
  })(0);
  function dmAbrir() {
    var el = document.getElementById('ork-dm-popup');
    if (el) { el.style.display = 'block'; dmAtualizarUI(); return; }
    el = document.createElement('div');
    el.id = 'ork-dm-popup';
    el.style.cssText = 'position:fixed;top:70px;right:20px;width:330px;max-height:85vh;overflow:auto;background:#1a1a1a;color:#eee;border:1px solid #3a3a3a;border-radius:10px;padding:10px;z-index:999999;font:12px "Segoe UI",Arial,sans-serif;box-shadow:0 10px 30px rgba(0,0,0,.7)';
    var campo = 'background:#111;color:#eee;border:1px solid #444;border-radius:5px;padding:3px 5px;width:80px';
    var tropasHtml = dmUnidades().map(function (u) {
      return '<label style="display:flex;justify-content:space-between;align-items:center;margin:2px 0">' + DM_NOMES[u] + ' <input type="number" min="0" data-u="' + u + '" style="' + campo + '"></label>';
    }).join('');
    el.innerHTML =
      '<div style="display:flex;justify-content:space-between;align-items:center;margin-bottom:6px"><b style="color:#FFC400;font-size:13px">🧱 Demolir de Muralhas</b><span id="dm-x" style="cursor:pointer;font-size:16px">&times;</span></div>' +
      '<div style="color:#999;font-size:10.5px;margin-bottom:8px">Manda a tropa abaixo pras bárbaras num raio em volta de cada aldeia sua, pra derrubar as muralhas.</div>' +
      '<div style="font-size:10px;color:#888;font-weight:800;text-transform:uppercase;margin-bottom:3px">Alvos e ritmo</div>' +
      '<label style="display:flex;justify-content:space-between;align-items:center;margin:2px 0">Raio (campos) <input type="number" id="dm-raio" min="1" style="' + campo + '"></label>' +
      '<label style="display:flex;justify-content:space-between;align-items:center;margin:2px 0">Intervalo entre ciclos (min) <input type="number" id="dm-int" min="1" style="' + campo + '"></label>' +
      '<label style="display:flex;justify-content:space-between;align-items:center;margin:2px 0">Máx. ataques por ciclo <input type="number" id="dm-max" min="1" style="' + campo + '"></label>' +
      '<label style="display:flex;justify-content:space-between;align-items:center;margin:2px 0">Ataques por aldeia do oponente <input type="number" id="dm-por" min="1" style="' + campo + '"></label>' +
      '<label style="display:flex;justify-content:space-between;align-items:center;margin:2px 0">Catapultas em alvo aleatório <input type="checkbox" id="dm-catrand"></label>' +
      '<label style="display:flex;justify-content:space-between;align-items:center;margin:2px 0">Velocidade <select id="dm-vel" style="' + campo + '"><option value="0.5">0.5x</option><option value="1">1x</option><option value="1.5">1.5x</option><option value="2">2x</option></select></label>' +
      '<div style="font-size:10px;color:#888;font-weight:800;text-transform:uppercase;margin:8px 0 3px">Tropas por ataque</div>' + tropasHtml +
      '<div style="display:flex;gap:6px;margin-top:10px"><button id="dm-salvar" style="flex:1;padding:6px;border:0;border-radius:6px;background:#2a2a2a;color:#FFC400;cursor:pointer">💾 Salvar</button><button id="dm-ligar" style="flex:1;padding:6px;border:0;border-radius:6px;background:linear-gradient(100deg,#FFB800,#FFDD55);color:#141200;font-weight:800;cursor:pointer">▶ Ligar</button><button id="dm-parar" style="flex:1;padding:6px;border:0;border-radius:6px;background:#2a1010;color:#ff6b6b;cursor:pointer">⏹ Parar</button></div>' +
      '<div id="dm-status" style="margin-top:8px;font-weight:800;color:#FFC400">Parado</div>' +
      '<div id="dm-log" style="margin-top:6px;max-height:180px;overflow:auto;font-size:10.5px;color:#bbb;background:#111;border-radius:6px;padding:6px"></div>';
    document.body.appendChild(el);
    dmAtualizarUI();
    var cfgAtual = dmLer();
    dmStatus(cfgAtual.ativo ? 'ligado' : 'Parado');
    document.getElementById('dm-x').addEventListener('click', function () { el.style.display = 'none'; });
    document.getElementById('dm-salvar').addEventListener('click', function () { var c = dmLerUI(); c.ativo = dmLer().ativo; dmGravar(c); dmLog('configuração salva.'); });
    document.getElementById('dm-ligar').addEventListener('click', function () {
      var c = dmLerUI(); c.ativo = true; dmGravar(c); dmParando = false;
      if (!dmRodando) { dmLog('ligado: ' + Object.keys(c.tropas).filter(function (u) { return c.tropas[u] > 0; }).map(function (u) { return c.tropas[u] + ' ' + DM_NOMES[u]; }).join(', ') + ' — raio ' + c.raio + '.'); dmCiclo(); }
    });
    document.getElementById('dm-parar').addEventListener('click', dmParar);
  }

