  /* ============================================================
     v157: RETOMAR ATAQUES SINCRONIZADOS (Ataque Mass com "Sincronizar chegada")
     Cada envio agendado fica salvo no navegador (horário de saída + dados da tropa). Se der captcha,
     "Solicitação bloqueada", recarregar a página ou relogar no meio, ao voltar ele confirma de novo
     e manda no MESMO horário programado — não perde a leva. Atrasado = sai o quanto antes (até 1h).
  ============================================================ */
  var AMX_FILA_TOKEN = 'p' + Math.random().toString(36).slice(2, 10);
  function amxFilaChave() { return 'ork_amx_fila_' + ((window.game_data && game_data.world) || ''); }
  function amxFilaLer() { var f = null; try { f = JSON.parse(localStorage.getItem(amxFilaChave()) || 'null'); } catch (e) {} if (!f || typeof f !== 'object') { f = {}; } if (!f.itens || typeof f.itens !== 'object') { f.itens = {}; } if (!f.vivo || typeof f.vivo !== 'object') { f.vivo = {}; } return f; }
  function amxFilaGravar(f) { try { if (!Object.keys(f.itens).length) { localStorage.removeItem(amxFilaChave()); } else { localStorage.setItem(amxFilaChave(), JSON.stringify(f)); } } catch (e) {} }
  window.orkAmxFilaAdd = function (aldeia, sendAt, targetTs) {
    try {
      if (!aldeia || !aldeia.dataPre) { return null; }
      var k = aldeia.id + '>' + (aldeia.alvoId || aldeia.alvoC) + '@' + targetTs;
      var f = amxFilaLer();
      var novo = !f.itens[k];
      f.itens[k] = { vid: aldeia.id, coord: aldeia.coord, alvoC: aldeia.alvoC, alvoId: aldeia.alvoId, dataPre: aldeia.dataPre, building: aldeia.building || '', sendAt: Math.round(sendAt), alvoTs: targetTs, st: 'agendado', dono: AMX_FILA_TOKEN, tent: (f.itens[k] && f.itens[k].tent) || 0 };
      if (novo) { f.total = (f.total || 0) + 1; } // v204: total pra bolinha (saíram/faltam)
      f.vivo[AMX_FILA_TOKEN] = Date.now(); amxFilaGravar(f);
      return k;
    } catch (e) { return null; }
  };
  // v204: bolinha do sincronizador — aparece em qualquer tela mostrando quantos saíram e quantos faltam
  function amxBolinha(rem, total) {
    try {
      var b = document.getElementById('ork-sync-bolinha');
      if (!rem) { if (b) { b.remove(); } return; }
      if (!document.body) { return; }
      var sent = Math.max(0, (total || 0) - rem);
      if (!b) {
        b = document.createElement('div'); b.id = 'ork-sync-bolinha';
        b.title = 'Ataques sincronizados na fila — saem no horário programado, mesmo trocando de tela/F5/captcha.';
        b.style.cssText = 'position:fixed;left:10px;bottom:170px;z-index:2147483600;background:linear-gradient(160deg,#1a1a1a,#050505);border:1px solid #8a6d00;color:#FFC400;font:700 11.5px "Segoe UI",Arial,sans-serif;padding:7px 11px;border-radius:20px;box-shadow:0 8px 20px rgba(0,0,0,.6);white-space:nowrap;pointer-events:auto';
        document.body.appendChild(b);
      }
      var txt = b.querySelector('.amx-bt'), bt = b.querySelector('.amx-canc');
      if (!txt) {
        b.innerHTML = '<span class="amx-bt"></span><button class="amx-canc" type="button" title="Cancelar todos os ataques sincronizados que ainda não saíram" style="margin-left:9px;background:#5a1414;color:#ffd0d0;border:1px solid #a33;border-radius:12px;font:700 11px Segoe UI,Arial,sans-serif;padding:3px 9px;cursor:pointer">✖ Cancelar</button>';
        txt = b.querySelector('.amx-bt'); bt = b.querySelector('.amx-canc');
        bt.addEventListener('click', function (e) {
          e.stopPropagation();
          if (bt.dataset.conf !== '1') {
            bt.dataset.conf = '1'; bt.textContent = 'Confirmar? cancela ' + (Object.keys(amxFilaLer().itens).length) + '';
            bt.style.background = '#a31d1d'; bt.style.color = '#fff';
            setTimeout(function () { if (bt.isConnected) { bt.dataset.conf = ''; bt.textContent = '✖ Cancelar'; bt.style.background = '#5a1414'; bt.style.color = '#ffd0d0'; } }, 5000);
            return;
          }
          window.orkAmxCancelarTodos();
        });
      }
      txt.innerHTML = '⚔️ Sincronizado: <b style="color:#7ed17e">' + sent + '</b> saíram · <b style="color:#ffd84d">' + rem + '</b> faltam';
    } catch (e) {}
  }
  // v235: cancelar os ataques sincronizados que ainda não saíram (botão na bolinha)
  function amxCancChave() { return 'ork_amx_cancelados_' + ((window.game_data && game_data.world) || ''); }
  window.orkAmxCancelado = function (k) {
    try { var c = JSON.parse(localStorage.getItem(amxCancChave()) || '{}'); return !!c[k]; } catch (e) { return false; }
  };
  window.orkAmxCancelarTodos = function () {
    try {
      var f = amxFilaLer(), ks = Object.keys(f.itens), c = {};
      try { c = JSON.parse(localStorage.getItem(amxCancChave()) || '{}'); } catch (e) {}
      var agora = Date.now();
      Object.keys(c).forEach(function (k) { if (agora - c[k] > 6 * 3600000) { delete c[k]; } }); // limpa os antigos
      ks.forEach(function (k) { c[k] = agora; delete f.itens[k]; });
      f.total = 0;
      localStorage.setItem(amxCancChave(), JSON.stringify(c));
      amxFilaGravar(f);
      amxBolinha(0, 0);
      console.log('[OROCHIKING] Sincronizador: ' + ks.length + ' ataque(s) agendado(s) cancelado(s).');
      try { if (window.UI && UI.SuccessMessage) { UI.SuccessMessage('✖ ' + ks.length + ' ataque(s) sincronizado(s) cancelado(s).', 4000); } } catch (e) {}
      return ks.length;
    } catch (e) { return 0; }
  };
  window.orkAmxFilaMarcar = function (k, st) { try { var f = amxFilaLer(); if (f.itens[k]) { f.itens[k].st = st; if (st === 'pendente') { f.itens[k].dono = ''; } amxFilaGravar(f); } } catch (e) {} };
  window.orkAmxFilaTirar = function (k) { try { var f = amxFilaLer(); delete f.itens[k]; amxFilaGravar(f); } catch (e) {} };
  (function amxFilaRetomada() {
    if (typeof game_data === 'undefined' || typeof $ === 'undefined') { return; }
    try { if (window.top !== window.self) { return; } } catch (e) { return; }
    var cursor = 0, avisou = false;
    function aviso(t) {
      try {
        var d = document.getElementById('ork-amx-retoma');
        if (!d) { d = document.createElement('div'); d.id = 'ork-amx-retoma'; d.style.cssText = 'position:fixed;top:12px;right:12px;z-index:2147483000;background:linear-gradient(160deg,#1a1a1a,#050505);border:1px solid #8a6d00;color:#FFC400;font:700 12px "Segoe UI",Arial,sans-serif;padding:8px 12px;border-radius:10px;box-shadow:0 10px 24px rgba(0,0,0,.6);max-width:340px'; document.body.appendChild(d); }
        d.textContent = t; clearTimeout(d.__t); d.__t = setTimeout(function () { d.remove(); }, 15000);
      } catch (e) {}
    }
    function post(url, data) { return new Promise(function (ok, ruim) { $.ajax({ type: 'POST', url: url, data: data, dataType: 'json', headers: { 'TribalWars-Ajax': 1 }, success: ok, error: function (x) { ruim(new Error('HTTP ' + (x && x.status))); } }); }); }
    function hs() { return Math.round(Timing.getCurrentServerTime() / 1e3); }
    async function mandar(k, it) {
      try {
        // confirma uns segundos antes da hora de sair (o jogo pede a confirmação fresca)
        var esperaConf = it.sendAt - 6000 - Date.now(); if (esperaConf > 0) { await new Promise(function (r) { setTimeout(r, esperaConf); }); }
        if (window.__ORK_CAPTCHA_BLOQUEADO__) { window.orkAmxFilaMarcar(k, 'pendente'); return; }
        if (window.orkAmxCancelado(k) || !amxFilaLer().itens[k]) { return; } // v235: cancelado
        var conf = await post('/game.php?village=' + it.vid + '&screen=place&ajax=confirm&h=' + csrf_token + '&client_time=' + hs(), it.dataPre);
        if (conf && conf.error) { throw new Error(String([].concat(conf.error).join(' '))); }
        var str = (it.dataPre && it.dataPre.string) || '';
        var dados = $(conf.response.dialog).serialize() + (str.length ? '&' + str : '');
        if (it.building) { dados = dados.replace(/([&?]|^)building=[^&]*/, ''); dados += '&building=' + encodeURIComponent(it.building); }
        var agora = Date.now(); cursor = Math.max(cursor, agora);
        var quando = Math.max(it.sendAt, cursor); cursor = quando + 220;
        if (quando - agora > 0) { await new Promise(function (r) { setTimeout(r, quando - agora); }); }
        if (window.orkAmxCancelado(k)) { return; } // v235: cancelado durante a espera
        if (window.__ORK_CAPTCHA_BLOQUEADO__) { window.orkAmxFilaMarcar(k, 'pendente'); return; }
        var r = await post('/game.php?village=' + it.vid + '&screen=place&ajaxaction=popup_command&h=' + csrf_token + '&client_time=' + hs(), dados);
        if (r && r.error) { throw new Error(String([].concat(r.error).join(' '))); }
        window.orkAmxFilaTirar(k);
        console.log('[OROCHIKING] Ataque retomado: ' + it.coord + ' → ' + it.alvoC + (Date.now() - it.sendAt > 3000 ? ' (saiu atrasado ' + Math.round((Date.now() - it.sendAt) / 1000) + 's)' : ' (no horário certo)') + '.');
      } catch (e) {
        if (window.__ORK_CAPTCHA_BLOQUEADO__) { window.orkAmxFilaMarcar(k, 'pendente'); return; }
        var f = amxFilaLer(), x = f.itens[k]; if (!x) { return; }
        x.tent = (x.tent || 0) + 1;
        if (x.tent >= 3) { delete f.itens[k]; console.warn('[OROCHIKING] Ataque retomado: desisti de ' + it.coord + ' → ' + it.alvoC + ' (' + ((e && e.message) || e) + ').'); }
        else { x.st = 'pendente'; x.dono = ''; x.sendAt = Math.max(x.sendAt, Date.now() + 3000); }
        amxFilaGravar(f);
      }
    }
    setInterval(function () {
      try {
        var f = amxFilaLer(), ks = Object.keys(f.itens);
        amxBolinha(ks.length, f.total); // v204: atualiza a bolinha em toda tela
        if (!ks.length) { avisou = false; return; }
        var agora = Date.now(), meus = 0;
        ks.forEach(function (k) { if (f.itens[k].dono === AMX_FILA_TOKEN && f.itens[k].st !== 'pendente') { meus++; } });
        if (meus) { f.vivo[AMX_FILA_TOKEN] = agora; amxFilaGravar(f); } // esta página ainda cuida dos agendados dela
        if (window.__ORK_CAPTCHA_BLOQUEADO__) { return; }
        var pegar = [];
        ks.forEach(function (k) {
          var it = f.itens[k];
          if (agora - it.sendAt > 3600000) { delete f.itens[k]; console.warn('[OROCHIKING] Ataque retomado: ' + it.coord + ' → ' + it.alvoC + ' passou mais de 1h do horário — descartado.'); return; }
          var donoMorto = !it.dono || (agora - (f.vivo[it.dono] || 0) > 12000);
          if (it.st === 'pendente' || ((it.st === 'agendado' || it.st === 'retomando' || it.st === 'enviando') && donoMorto && it.dono !== AMX_FILA_TOKEN)) { it.st = 'retomando'; it.dono = AMX_FILA_TOKEN; pegar.push(k); }
        });
        Object.keys(f.vivo).forEach(function (t) { if (agora - f.vivo[t] > 3600000) { delete f.vivo[t]; } });
        f.vivo[AMX_FILA_TOKEN] = agora;
        amxFilaGravar(f);
        if (!pegar.length) { return; }
        pegar.sort(function (a, b) { return f.itens[a].sendAt - f.itens[b].sendAt; });
        var atras = pegar.filter(function (k) { return f.itens[k].sendAt < agora; }).length;
        aviso('⚔️ OROCHIKING: retomando ' + pegar.length + ' ataque(s) sincronizado(s)' + (atras ? ' — ' + atras + ' já passaram do horário e saem agora' : ' no horário programado') + '.');
        console.log('[OROCHIKING] Retomando ' + pegar.length + ' ataque(s) sincronizado(s) que ficaram pendentes (captcha/bloqueio/recarregou).');
        pegar.forEach(function (k) { mandar(k, f.itens[k]); });
      } catch (e) {}
    }, 1000); // v204: era 2500ms — mais rápido pra pegar pendências quase na hora e o sincronismo ficar mais preciso
  })();

