    function marcar() { ids.forEach(function (id) { var b = document.getElementById(id); if (!b) { return; } if (!b.classList.contains('ork-chave')) { b.classList.add('ork-chave'); } var on = /ligado/i.test(b.textContent) && !/desligado/i.test(b.textContent) || b.classList.contains('ork-freio-on'); if (b.getAttribute('data-on') !== (on ? '1' : '0')) { b.setAttribute('data-on', on ? '1' : '0'); } if (!b.title) { b.title = 'Ligar / desligar'; } }); }
