  (function tornarArrastavel() {
    var header = document.getElementById('ork-header');
    var arrastando = false, offX = 0, offY = 0;
    header.addEventListener('mousedown', function (e) {
      // v97: clique no X / minimizar (ou em qualquer botão do topo) NÃO começa a arrastar —
      // antes o painel pulava pro lado esquerdo e era preciso clicar no X duas vezes
      if (e.target.closest && e.target.closest('#ork-close, #ork-min, button, a, input, select, label')) { return; }
      arrastando = true;
      var r = painel.getBoundingClientRect();
      offX = e.clientX - r.left;
      offY = e.clientY - r.top;
      // fixa a posição atual antes de soltar o "right" (senão o painel pula)
      painel.style.left = r.left + 'px';
      painel.style.top = r.top + 'px';
      painel.style.right = 'auto';
      e.preventDefault();
    });
    document.addEventListener('mousemove', function (e) {
      if (!arrastando) return;
      painel.style.left = (e.clientX - offX) + 'px';
      painel.style.top = (e.clientY - offY) + 'px';
    });
    document.addEventListener('mouseup', function () { arrastando = false; });
  })();

  // v163: o X só esconde — a bolinha do painel (canto esquerdo) abre de novo na hora
  document.getElementById('ork-close').addEventListener('click', function () { painel.style.display = 'none'; });

